import React from "react";
import ProtectionCard from "$Popup/components/FullProtection/ProtectionCard";
import PlatformIcons from "$Popup/components/FullProtection/PlatformIcons";
import { useProtectionCardStatus } from "./useProtectionCardStatus";

const ProtectionCardList: React.FC = () => {
  const { cards, isLoading } = useProtectionCardStatus();

  if (isLoading) {
    return (
      <div data-testid="div-202d31ab"  className="flex flex-col gap-6">
        {cards.map((card, idx) => (
          <ProtectionCard
            key={card.id + idx}
            {...card}
            statusVariant="info"
            footerContent={<PlatformIcons />}
          />
        ))}
      </div>
    );
  }

  return (
    <div data-testid="div-03bc1652"  className="flex flex-col gap-6">
      {cards.map((card, idx) => (
        <ProtectionCard
          key={card.id + idx}
          {...card}
          statusVariant={card.statusVariant}
          footerContent={<PlatformIcons />}
        />
      ))}
    </div>
  );
};

export default ProtectionCardList;
