import { useState, useEffect, useCallback } from 'react';
import { sendBackgroundMessage } from '@/utils/messaging/messaging';
import { MSG_ALLOW_GET_ALL, MSG_REM_ALLOW_DOMAIN } from '@/app/scripts/app-consts';
import { transformAllowListData, DELETE_ALL_MARKER } from '$Popup/utils/allowListData';
import type { Website, DeleteModalState } from './types';

/**
 * Custom hook for managing allow list data
 */
export const useAllowListData = (refreshKey?: number) => {
  const [websites, setWebsites] = useState<Website[]>([]);
  const [loading, setLoading] = useState(true);

  const loadAllowList = useCallback(async () => {
    try {
      setLoading(true);
      const response = await sendBackgroundMessage({ type: MSG_ALLOW_GET_ALL });
      
      if (response.success) {
        const websiteList = transformAllowListData(response.success);
        setWebsites(websiteList);
      }
    } catch (error) {
      console.error('Failed to load allow list:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadAllowList();
  }, [loadAllowList, refreshKey]);

  return { websites, loading, setWebsites, refetch: loadAllowList };
};

/**
 * Custom hook for managing delete operations
 */
export const useDeleteOperations = (websites: Website[], setWebsites: React.Dispatch<React.SetStateAction<Website[]>>) => {
  const [deleteModal, setDeleteModal] = useState<DeleteModalState>({
    isOpen: false,
    websiteToDelete: null,
    isDeleting: false
  });

  const openDeleteModal = useCallback((website: Website) => {
    setDeleteModal({
      isOpen: true,
      websiteToDelete: website,
      isDeleting: false
    });
  }, []);

  const openDeleteAllModal = useCallback(() => {
    setDeleteModal({
      isOpen: true,
      websiteToDelete: { domain: DELETE_ALL_MARKER, exclusions: [] },
      isDeleting: false
    });
  }, []);

  const closeDeleteModal = useCallback(() => {
    setDeleteModal({
      isOpen: false,
      websiteToDelete: null,
      isDeleting: false
    });
  }, []);

  const confirmDelete = useCallback(async () => {
    if (!deleteModal.websiteToDelete) return;

    setDeleteModal(prev => ({ ...prev, isDeleting: true }));

    try {
      if (deleteModal.websiteToDelete.domain === DELETE_ALL_MARKER) {
        // Delete all websites
        const deletePromises = websites.map(website => 
          sendBackgroundMessage({
            type: MSG_REM_ALLOW_DOMAIN,
            payload: { host: website.domain }
          })
        );

        await Promise.all(deletePromises);
        setWebsites([]);
      } else {
        // Delete single website
        const response = await sendBackgroundMessage({
          type: MSG_REM_ALLOW_DOMAIN,
          payload: { host: deleteModal.websiteToDelete.domain }
        });

        if (response.success || !response.error) {
          setWebsites(prev => prev.filter(w => w.domain !== deleteModal.websiteToDelete!.domain));
        } else {
          console.error('Failed to delete website:', response.error);
          // TODO: Show error notification to user
        }
      }

      closeDeleteModal();
    } catch (error) {
      console.error('Error deleting website(s):', error);
      // TODO: Show error notification to user
    } finally {
      setDeleteModal(prev => ({ ...prev, isDeleting: false }));
    }
  }, [deleteModal.websiteToDelete, websites, setWebsites, closeDeleteModal]);

  return {
    deleteModal,
    openDeleteModal,
    openDeleteAllModal,
    closeDeleteModal,
    confirmDelete
  };
};
