// ABOUTME: Hook for managing manual ad removal table configuration and modal state
// ABOUTME: Handles table columns, delete modals, and confirmation logic

import React, { useState, useMemo, useCallback } from 'react'
import { ColumnDef, createColumnHelper } from '@tanstack/react-table'
import { BGSvgIcon, useModal } from '$Popup/components/core'
import BGContextMenu from '$Popup/components/core/BGContextMenu'
import { MenuButton } from '$Popup/components/core/BGContextMenu'
import { t } from '$Popup/i18n'
import { BlockedItemRow, BlockedItemData } from './useManualAdRemoval'

const columnHelper = createColumnHelper<BlockedItemRow>()

interface UseManualAdRemovalTableParams {
  rows: BlockedItemRow[]
  onDeleteOne: (item: BlockedItemData) => Promise<boolean>
  onDeleteAll: () => Promise<boolean>
}

export const useManualAdRemovalTable = ({
  rows,
  onDeleteOne,
  onDeleteAll,
}: UseManualAdRemovalTableParams) => {
  const deleteModal = useModal()
  const [isDeleteAll, setIsDeleteAll] = useState(false)
  const [selectedRow, setSelectedRow] = useState<BlockedItemRow | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)

  const handleDeleteOne = useCallback(
    async (row: BlockedItemRow) => {
      await onDeleteOne({
        domain: row.address,
        blockUrls: [],
        xpath: row.xPath,
      })
    },
    [onDeleteOne]
  )

  const handleDeleteOneClicked = useCallback(
    (rowData: BlockedItemRow) => () => {
      setIsDeleteAll(false)
      setSelectedRow(rowData)
      deleteModal.openModal()
    },
    [deleteModal]
  )

  const handleDeleteAllClicked = useCallback(() => {
    setIsDeleteAll(true)
    deleteModal.openModal()
  }, [deleteModal])

  const handleOnConfirmModal = useCallback(async () => {
    if (isDeleting) return

    setIsDeleting(true)
    try {
      if (isDeleteAll) {
        await onDeleteAll()
      } else if (selectedRow) {
        await handleDeleteOne(selectedRow)
        setSelectedRow(null)
      } else {
        console.warn('No action specified for confirmation modal')
        return
      }
      deleteModal.closeModal()
    } catch (error) {
      console.error('Error during deletion:', error)
    } finally {
      setIsDeleting(false)
    }
  }, [
    isDeleting,
    isDeleteAll,
    selectedRow,
    onDeleteAll,
    handleDeleteOne,
    deleteModal,
  ])

  const columns = useMemo<ColumnDef<BlockedItemRow, any>[]>(
    () => [
      columnHelper.accessor('address', {
        header: t('UrlOrIPAddress'),
        cell: (info) => (
          <div data-testid="div-f1410f88" >
            <div data-testid="div-eaf808a5"  className="title-medium ">{info.getValue() || 'N/A'}</div>
            <p data-testid="p-529db554"  className="text-xs dark:text-[#FFFFFF80]  text-[#1C1B1F80]  break-all">
              {info.row.original.xPath}
            </p>
          </div>
        ),
      }),

      columnHelper.display({
        id: 'actions',
        header: () =>
          rows.length > 0 ? (
            <BGContextMenu
              trigger={
                <button data-testid="button-65f8ecbd" 
                  className="p-1 hover:bg-tragic-100 rounded transition-colors"
                  aria-label="Actions menu"
                >
                  <BGSvgIcon
                    iconName="kebab-menu"
                    size={16}
                    className="opacity-60 hover:opacity-100"
                  />
                </button>
              }
            >
              <MenuButton
                onClick={handleDeleteAllClicked}
                className="text-danger hover:bg-danger-100"
              >
                {t('DeleteAll')}
              </MenuButton>
            </BGContextMenu>
          ) : null,
        cell: (info) => (
          <BGContextMenu
            trigger={
              <button data-testid="button-f8e752b5" 
                className="p-1 hover:bg-tragic-100 rounded transition-colors"
                aria-label={`Menu for ${info.row.original.address}`}
              >
                <BGSvgIcon
                  iconName="kebab-menu"
                  size={16}
                  className="opacity-60 hover:opacity-100"
                />
              </button>
            }
          >
            <MenuButton
              onClick={handleDeleteOneClicked(info.row.original)}
              className="text-danger hover:bg-danger-100"
            >
              {t('Delete')}
            </MenuButton>
          </BGContextMenu>
        ),
        size: 96,
        meta: {
          headerClassName: 'w-24 text-right',
          cellClassName: 'py-3 px-4 text-right',
          align: 'right',
        },
      }),
    ],
    [rows, handleDeleteAllClicked, handleDeleteOneClicked]
  )

  const modalConfig = useMemo(
    () => ({
      isOpen: deleteModal.isOpen,
      onClose: deleteModal.closeModal,
      onConfirm: handleOnConfirmModal,
      loading: isDeleting,
      title: isDeleteAll
        ? t('RemoveAllAdsConfirmation')
        : t('RemoveAdsConfirmation'),
      description: isDeleteAll
        ? t('RemoveAllAdsWarning')
        : t('RemoveAdsWarning'),
      cancelLabel: t('Cancel'),
      confirmLabel: isDeleteAll ? t('RemoveAllBtn') : t('RemoveBtn'),
      loadingLabel: isDeleteAll ? t('RemovingAll') : t('Removing'),
      confirmButtonClassName: 'bg-primary text-backdrop hover:[background-color:var(--color-primary-hover)]',
    }),
    [
      deleteModal.isOpen,
      deleteModal.closeModal,
      handleOnConfirmModal,
      isDeleting,
      isDeleteAll,
    ]
  )

  return {
    columns,
    modalConfig,
  }
}
