import { create } from 'zustand'
import { createGeneralSettingsSlice } from './slices/generalSettingsSlice'
import { createTabSlice } from './slices/tabSlice'
import { createSiteProtectionSlice } from './slices/siteProtectionSlice'
import { createBlockedItemsSlice } from './slices/blockedItemsSlice'
import {
  GeneralSettingsSlice,
  TabSlice,
  SiteProtectionSlice,
  BlockedItemsSlice,
} from './types'
import { useShallow } from 'zustand/react/shallow'
// Combined store interface
export interface ExtensionStore
  extends GeneralSettingsSlice,
    TabSlice,
    SiteProtectionSlice,
    BlockedItemsSlice {}

// Main store combining all slices
export const useExtensionStore = create<ExtensionStore>()((...a) => ({
  ...createGeneralSettingsSlice(...a),
  ...createTabSlice(...a),
  ...createSiteProtectionSlice(...a),
  ...createBlockedItemsSlice(...a),
}))

// Note: Store initialization now happens in individual components via useEffect

// Export individual slice hooks for convenience
export const useGeneralSettings = () =>
  useExtensionStore(
    useShallow((state) => ({
      enableProtection: state.enableProtection,
      enableProtectionAds: state.enableProtectionAds,
      enableProtectionScams: state.enableProtectionScams,
      enableProtectionMalware: state.enableProtectionMalware,
      enableProtectionGtld: state.enableProtectionGtld,
      enableShowBlockCount: state.enableShowBlockCount,
      enableMonthlyNotification: state.enableMonthlyNotification,
      enableMaliciousNotification: state.enableMaliciousNotification,
      enableNewReleaseNotification: state.enableNewReleaseNotification,
      enableBlockCountDisplay: state.enableBlockCountDisplay,
      enableSkimmerProtection: state.enableSkimmerProtection,
      enableBreachNotification: state.enableBreachNotification,
      enableSearchHijackingNotification: state.enableSearchHijackingNotification,
      enableProfileCheckerNotification: state.enableProfileCheckerNotification,
      enableVerboseLogging: state.enableVerboseLogging,
      enableClipboardReadPermission: state.enableClipboardReadPermission,
      enablePrivacyPermission: state.enablePrivacyPermission,
      hasSeenAiScannerPopover: state.hasSeenAiScannerPopover,
    }))
  )

// Individual general settings action selectors
export const useToggleGeneralProtection = () =>
  useExtensionStore((state) => state.toggleGeneralProtection)
export const useToggleGeneralProtectionLayer = () =>
  useExtensionStore((state) => state.toggleGeneralProtectionLayer);
export const useToggleClipboardPermission = () =>
  useExtensionStore((state) => state.toggleClipboardPermission)
export const useTogglePrivacyPermission = () =>
  useExtensionStore((state) => state.togglePrivacyPermission)
export const useDismissAiScannerPopover = () =>
  useExtensionStore((state) => state.dismissAiScannerPopover)

// General settings loading state selector
export const useGeneralSettingsLoading = () =>
  useExtensionStore((state) => state.isLoading);
export const useLoadGeneralSettings = () =>
  useExtensionStore((state) => state.loadGeneralSettings)

export const useTabData = () =>
  useExtensionStore((state) => ({
    tabsData: state.tabsData,
    currentTabId: state.currentTabId,
    isLoading: state.isLoading,
    // Return the function, don't call it here
    getCurrentTabData: state.getCurrentTabData,
  }))

// Individual tab action selectors
export const useSetCurrentTabId = () =>
  useExtensionStore((state) => state.setCurrentTabId)
export const useGetCurrentTabData = () =>
  useExtensionStore((state) => state.getCurrentTabData)
export const useLoadTabsData = () =>
  useExtensionStore((state) => state.loadTabsData)

// Individual site protection state selectors
export const useSiteProtections = () =>
  useExtensionStore((state) => state.siteProtections)
export const useSiteProtectionLoading = () =>
  useExtensionStore((state) => state.isLoading)

// Individual site protection action selectors
export const useToggleSiteProtection = () =>
  useExtensionStore((state) => state.toggleSiteProtection)
export const useIsSiteProtected = () =>
  useExtensionStore((state) => state.isSiteProtected)
export const useLoadSiteProtections = () =>
  useExtensionStore((state) => state.loadSiteProtections)
export const useSetSiteProtections = () =>
  useExtensionStore((state) => state.setSiteProtections)
export const useGetSiteProtections = () =>
  useExtensionStore((state) => state.getSiteProtections)
export const useClearAllSiteProtections = () =>
  useExtensionStore((state) => state.clearAllSiteProtections)

// Blocked items selectors
export const useBlockedItems = () =>
  useExtensionStore((state) => state.blockedItemsByDomain)
export const useLoadBlockedItems = () =>
  useExtensionStore((state) => state.loadBlockedItems)
export const useDeleteBlockedItem = () =>
  useExtensionStore((state) => state.deleteBlockedItem)
export const useDeleteAllBlockedItems = () =>
  useExtensionStore((state) => state.deleteAllBlockedItems)
export const useAllBlockedItems = () =>
  useExtensionStore((state) => state.getAllItems)

// Tutorial selectors
export const useShowTutorial = () =>
  useExtensionStore((state) => state.showTutorial);
export const useInitShowTutorial = () =>
  useExtensionStore((state) => state.initShowTutorial);
export const useSetShowTutorialDone = () =>
  useExtensionStore((state) => state.setShowTutorialDone);
