import * as React from "react";
import { DataTable, TableEmptyState } from "$Popup/components/core/BGTable";
import DeleteConfirmModal from "../DeleteConfirmModal";
import { useAllowListData, useDeleteOperations } from "./hooks";
import { createColumns } from "./columns";
import type { AllowListTableProps } from "./types";
import { t } from "$Popup/i18n";

const AllowListTable: React.FC<AllowListTableProps> = ({ refreshKey }) => {
  const { websites, loading, setWebsites } = useAllowListData(refreshKey);
  const { deleteModal, openDeleteModal, openDeleteAllModal, closeDeleteModal, confirmDelete } = 
    useDeleteOperations(websites, setWebsites);

  const columns = createColumns(websites, openDeleteModal, openDeleteAllModal);

  if (loading) {
    return (
      <div data-testid="div-0dba9aa2"  className="flex justify-center items-center py-8">
        <span data-testid="span-0d4a3cb7" >{t("Loading")}</span>
      </div>
    );
  }

  return (
    <>
      <div data-testid="div-ec1b4324"  className="w-full">
        <DataTable 
          columns={columns} 
          data={websites} 
          emptyState={
            <TableEmptyState 
              title={t("NoItemsAdded")}
              description={t('manualAdRemovalSummary2')}
            />
          }
          enableSearch={true}
          searchPlaceholder={t("SearchDomainsPlaceholder")+'...'}
        />
      </div>

      <DeleteConfirmModal
        isOpen={deleteModal.isOpen}
        onClose={closeDeleteModal}
        onConfirm={confirmDelete}
        loading={deleteModal.isDeleting}
        websiteDomain={deleteModal.websiteToDelete?.domain}
      />
    </>
  );
};

export default AllowListTable;
