import { useAppNavigation } from '$Popup/routes/hooks';
import { BGModal, BGSvgIcon, Card, useModal } from '$Popup/components/core';
import { buildRecentActivity, RecentActivity, showResultsViewForActivity, startGoogleScan } from './logic';
import { t } from '$Popup/i18n';
import { useEffect, useState } from 'react';
import { useOAPPage } from './hooks/useOapPage';
import { OAPActionNoticeModalContent } from './injectable/oap-action-notice';


const OAP: React.FC = () => {
    const { isFirstTime, checkIfFirstTime } = useOAPPage();    
    const oapNoticeModal = useModal();

    const onStartGoogleScan = async () => {
        oapNoticeModal.openModal();                
    };

    const onStartScanConfirmed = async (dontShowAgain?: boolean, cancel?: boolean) => {
        if (cancel === true) {
            return;
        }
        startGoogleScan().then((started) => {
            console.log('Start Google Scan: ', started);
        });
    }

    useEffect(() => {
        checkIfFirstTime();
    }, [checkIfFirstTime]);

    return (
        <div data-testid="div-36d2c8cc"  className="OAP min-h-screen mx-auto flex flex-col gap-4">
            {/* Header */}
            <div data-testid="div-ebb6f116"  className="flex flex-col space-y-2">
                <h3 data-testid="h3-33c2f7d8" >{t('OAPTitle')}</h3>
                <p data-testid="p-da813f0a"  className="opacity-80">{t('OAPDescription')}</p>
            </div>

            {/* OAP content */}
            {isFirstTime && (<Card className="">
                <div data-testid="div-cee40944"  className="flex flex-row gap-6 items-center">
                    <BGSvgIcon iconName="oap-scan-tools" size={100} />
                    <div data-testid="div-7327c594"  className="flex flex-col gap-1 justify-start">
                        <h2 data-testid="h2-ad5f1bc8"  className="text-xl font-[500] leading-7">{t('OAPStartYourFirstScan')}</h2>
                        <p data-testid="p-db3a64d6"  className="text-sm tracking-[0.25px]">{t('OAPStartYourFirstScanDescription')}</p>
                    </div>
                    <div data-testid="div-2267f031" >
                        <button data-testid="button-0213065b" 
                            onClick={onStartGoogleScan}
                            className="bg-primary w-40 flex py-2.5 px-6 justify-center align-middle gap-2 rounded-4xl text-sm text-backdrop font-medium leading-5 tracking-[0.1px]">
                            {t('OAPScanNow')}
                        </button>
                    </div>
                </div>
            </Card>)}

            <Card>
                <div data-testid="div-b9f55c62"  className="flex flex-col gap-1 justify-start">
                    <h2 data-testid="h2-a8322fee"  className="text-[22px] font-medium leading-7">{t('OAPScanSettings')}</h2>
                    <p data-testid="p-c2ec1df1"  className="text-sm font-normal leading-5 tracking-[0.25px]">{t('OAPScanSettingsDescription')}</p>
                </div>

                <div data-testid="div-dd80cd5f"  className="flex flex-col gap-2 w-full items-start justify-start mt-4">
                    <OAPScanButton onClick={onStartGoogleScan} iconName="google" title={t('OAPGoogleScanTitle')} description={t('OAPGoogleScanDescription')} />
                </div>
            </Card>

            <Card className=''>
                <div data-testid="div-e54d9446"  className="flex flex-col gap-1 justify-start mb-4">
                    <h2 data-testid="h2-5cd6b9e7"  className="text-[22px] font-medium leading-7">{t('OAPRecentActivityTitle')}</h2>
                    <p data-testid="p-5db3ad91"  className="text-sm font-normal leading-5 tracking-[0.25px]">{t('OAPRecentActivityDescription')}</p>
                </div>
                {/* Recent activity */}
                <RecentActivityView />
            </Card>

            <OAPActionNoticeModal isOpen={oapNoticeModal.isOpen} onClose={() => {}} onComplete={(dontShowAgain, cancel) => {
                oapNoticeModal.closeModal();
                onStartScanConfirmed(dontShowAgain, cancel);
            }} />
        </div>
    );
};

const OAPScanButton: React.FC<{ onClick: () => void, iconName: string, title: string, description: string, disabled?: boolean }> = ({ onClick, iconName, title, description, disabled }) => {
    return <button data-testid="button-5a0d6da5" 
        className="bg-backdrop hover:bg-tragic-100 flex flex-row w-full px-6 py-4 gap-2.5 self-stretch cursor-pointer rounded-lg items-center border border-tragic-200 transition-colors dark:border-[#414451]"
        onClick={onClick}
        disabled={disabled}
        aria-label={`Scan ${title}`}
        title={`Scan ${title}`}
    >
        <BGSvgIcon iconName={iconName} isNeutral size={24} />
        <div data-testid="div-baa829fa"  className="flex flex-col items-start justify-center gap-1">
            <h4 data-testid="h4-09d84f20"  className="text-base font-medium leading-6 tracking-[0.15px]">{title}</h4>
            <p data-testid="p-358f24a9"  className="text-sm font-normal leading-5 tracking-[0.25px] opacity-80">{description}</p>
        </div>
    </button>
};

const RecentActivityView: React.FC = () => {
    const [recentActivity, setRecentActivity] = useState<RecentActivity[]>([]);

    useEffect(() => {
        buildRecentActivity().then((recentActivity) => {
            setRecentActivity(recentActivity);
        });
    }, []);

    const onActivityClicked = (activity: RecentActivity) => {
        // Show the results view for the activity
        showResultsViewForActivity(activity.scan).then((success) => {
            console.log('Show results view for activity: ', success);
        });
    };

    return (<>
        <div data-testid="div-b02085c9"  className="flex flex-col items-start w-full">
            <div data-testid="div-85a439d7"  className="bg-tragic-100 py-2 px-6 w-full">
                <p data-testid="p-06e5b21d"  className='text-tragic opacity-80 text-sm font-normal leading-5 tracking-[0.25px]'>{recentActivity.length > 0 ? t('OAPRecentActivityTableTitle') : t('OAPRecentActivityEmptyTableTitle')}</p>
            </div>

            <div data-testid="div-8051342d"  className='flex flex-col w-full'>
                {recentActivity.map((activity, index) => (
                    <RecentActivityItem key={index} activity={activity} onActivityClicked={() => onActivityClicked(activity)} />
                ))}
            </div>
        </div>
    </>);
};

const RecentActivityItem: React.FC<{ activity: RecentActivity, onActivityClicked: () => void }> = ({ activity, onActivityClicked }) => {
    const [scanTypeIcon, setScanTypeIcon] = useState<string | undefined>(undefined);
    useEffect(() => {
        // determine the icon for the scan type
        switch (activity.scan.scanType) {
            case 'google':
                setScanTypeIcon('google');
                break;
            case 'linkedin':
                setScanTypeIcon('linkedin-round');
                break;
            case 'x':
                setScanTypeIcon('x-round');
                break;
            default:
                setScanTypeIcon(undefined);
        }
    }, [activity.scan.scanType]);

    const calculateTimeDifference = (startDate: string) => {
        const locale = navigator.language;
        const now = Date.now();
        const past = new Date(startDate).getTime();
        const diffInSeconds = Math.floor((past - now) / 1000);
        
        const rtf = new Intl.RelativeTimeFormat(locale, { numeric: 'auto' });
        
        const units: { unit: Intl.RelativeTimeFormatUnit; seconds: number }[] = [
            { unit: 'year', seconds: 31536000 },
            { unit: 'month', seconds: 2592000 },
            { unit: 'week', seconds: 604800 },
            { unit: 'day', seconds: 86400 },
            { unit: 'hour', seconds: 3600 },
            { unit: 'minute', seconds: 60 },
            { unit: 'second', seconds: 1 }
        ];
        
        for (const { unit, seconds } of units) {
            if (Math.abs(diffInSeconds) >= seconds || unit === 'second') {
                const value = Math.floor(diffInSeconds / seconds);
                return rtf.format(value, unit);
            }
        }
        
        return rtf.format(0, 'second');
    };

    return <div data-testid="div-958f7ce3"  className="flex flex-row items-center justify-start w-full px-4 py-4 gap-2.5 border-b border-tragic-table-border cursor-pointer" onClick={onActivityClicked}>
        {scanTypeIcon && (
            <BGSvgIcon iconName={scanTypeIcon} size={24} isNeutral />
        )}
        <div data-testid="div-228f5c0f"  className='flex flex-col items-start justify-center grow shrink-0 basis-0'>
            <h4 data-testid="h4-4658ff9d"  className='text-base font-medium leading-6 tracking-[0.15px]'>Google scan complete</h4>
            <p data-testid="p-03e07265"  className='text-tragic opacity-50 text-sm font-normal leading-5 tracking-[0.25px]'>Check report and recommendation of the scan.</p>
        </div>
        <div data-testid="div-141b254f"  className='flex flex-row items-center justify-center'>
            <p data-testid="p-4d749bb0"  className='text-tragic opacity-50 text-sm font-normal leading-5 tracking-[0.25px]'>{calculateTimeDifference(activity.scan.startDate.toString())}</p>
        </div>
        <BGSvgIcon iconName="chevron-up" width={24} height={24} className='rotate-90' />
    </div>
};

const OAPActionNoticeModal: React.FC<{ isOpen: boolean, onClose: () => void, onComplete: (dontShowAgain?: boolean, cancel?: boolean) => void }> = ({ isOpen, onClose, onComplete }) => {
    return (
        <BGModal isOpen={isOpen} onClose={() => {}}>
            <OAPActionNoticeModalContent title={t('OAPActionNoticeTitleScan')} onComplete={onComplete} />
        </BGModal>
    );
};

export default OAP;