import React from 'react';
import BGSvgIcon from '$Popup/components/core/BGSvgIcon';
import { t } from '$Popup/i18n';
import { BGLink } from '$Popup/components/core/BGLink';
import { ROUTES } from '$Popup/routes/constants';
import { navigationUtils } from '$Popup/routes/hooks';
import type { ProtectionItem, ProtectionStatus } from './types';

/**
 * Individual protection item component
 */
export const ProtectionItemCard: React.FC<{ item: ProtectionItem }> = ({ item }) => {
    const isClickable = !!item.relatedFeatureRoute;
    
    const handleClick = () => {
        if (item.relatedFeatureRoute) {
            navigationUtils.navigateToPath(item.relatedFeatureRoute.path);
        }
    };

    return (
        <div 
            data-testid={`div-83d05db9-${item.labelKey}`}
            className={`bg-backdrop border border-tragic-200 rounded-lg px-6 py-4 flex items-center justify-between ${
                isClickable ? 'cursor-pointer hover:shadow-sm transition-all' : ''
            }`}
            onClick={isClickable ? handleClick : undefined}
            role={isClickable ? 'button' : undefined}
            tabIndex={isClickable ? 0 : undefined}
            onKeyDown={isClickable ? (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    handleClick();
                }
            } : undefined}
        >
            <div data-testid="div-a28003c2"  className="flex items-center space-x-3">
                <BGSvgIcon iconName={item.iconName} size={24} />
                <span data-testid="span-c5aa6d13"  className="text-base font-medium text-tragic">
                    {t(item.labelKey)}
                </span>
            </div>

            <div data-testid="div-3bc43d6e"  className="flex items-center space-x-2">
                {item.status === 'LOCKED' ? (
                    <BGSvgIcon iconName='yellow-lock' className='mr-1' size={27} />
                ) : (
                    <span data-testid="span-7eb495d3" 
                        className={`text-xs font-bold px-2 py-1 rounded-full ${item.status === 'OFF'
                            ? 'bg-warning-100 text-warning'
                            : 'bg-success-100 text-success'
                            }`}
                    >
                        {item.status}
                    </span>
                )}
            </div>
        </div>
    );
};

/**
 * Shield status display component
 */
export const ShieldStatus: React.FC<{ protectionStatus: ProtectionStatus }> = ({ protectionStatus }) => (
    <div data-testid="div-8bb1090b"  className="w-3/12 flex flex-col items-center justify-between text-center gap-3">
        <h4 data-testid="h4-5e44c7c3"  className="text-base font-medium text-tragic">
            Browser Guard
        </h4>
        <BGSvgIcon iconName={protectionStatus.iconName} size={90} />
        <p data-testid="p-c9a60624"  id="protection-status-text" className={`text-lg font-semibold ${protectionStatus.statusClass}`}>
            {protectionStatus.statusText}
        </p>
    </div>
);

/**
 * Protection settings grid component
 */
export const ProtectionGrid: React.FC<{ protectionItems: ProtectionItem[] }> = ({ protectionItems }) => (
    <div data-testid="div-ad049957"  className="w-9/12 flex flex-col justify-between">
        <div data-testid="div-acf621bc"  className="flex flex-row justify-between items-center mt-1">
            <p data-testid="p-c0fb4642" >
                {t('protectionSettingsDescription')}
            </p>
            <BGLink
                to={ROUTES.SETTINGS.name}
                className="text-primary text-sm font-medium hover:underline">
                {t('websiteProtectionsButton')}
            </BGLink>
        </div>

        <div data-testid="div-acbe3d05"  className="grid grid-cols-2 gap-y-2 gap-x-4 w-full">
            {protectionItems.map((item) => (
                <ProtectionItemCard
                    key={item.storeKey}
                    item={item}
                />
            ))}
        </div>
    </div>
);
