import { sendBackgroundMessage } from '@/utils/messaging/messaging';
import { 
    GetAllowGranularResponse, 
    GetAllowGranularRequest,
    SetAllowGranularRequest,
    SetAllowGranularResponse
} from '@/utils/messaging/types';
import { MSG_GET_ALLOW_GRANULAR, MSG_SET_ALLOW_GRANULAR } from '@/app/scripts/app-consts'

/**
 * Used in the popup dashboard blocked items list logic.
 * Gets the granular allow status for a URL.
 * @param url The URL to check
 * @param blockUrl Optional block URL to check against
 * @returns A promise that resolves to the allow status response
 */
export async function getAllowGranular(url: string, blockUrl?: string): Promise<GetAllowGranularResponse> {
    const request: GetAllowGranularRequest = { url, blockUrl };
    const response =  await sendBackgroundMessage<GetAllowGranularRequest, GetAllowGranularResponse>({
        type: MSG_GET_ALLOW_GRANULAR,
        payload: request
    });
    return response.payload || { value: false };
}

/**
 * Sets the granular allow status for a URL.
 * Used in the popup dashboard blocked items list logic.
 * @param url The URL to set allow status for
 * @param blockUrl The block URL to set against
 * @param value The allow value (true to allow, false to block)
 * @returns A promise that resolves with the set value when the operation is complete
 */
export async function setAllowGranular(request: SetAllowGranularRequest): Promise<SetAllowGranularResponse> {
    const response = await sendBackgroundMessage<SetAllowGranularRequest, SetAllowGranularResponse>({
        type: MSG_SET_ALLOW_GRANULAR,
        payload: request
    });
    return response.payload || { value: false };
}
