// ABOUTME: Route guard component that blocks access to routes based on OS, language,
// ABOUTME: feature flags, and browser constraints — mirroring LeftSidebar visibility rules.

import React, { useMemo } from 'react';
import { Outlet, Navigate, useLocation } from 'react-router-dom';
import { ROUTES } from './constants';
import { isRouteAllowed } from './filters';
import { RouteProps } from './types';
import { useFeatureFlags, useOperatingSystem } from '$Popup/utils/general';
import { uiLanguage } from '@/utils/locales';
import { TARGET_BROWSER } from '@/app/scripts/browser-const';

/**
 * RouteGuard Component
 *
 * Acts as a layout route wrapper that enforces route-level access control.
 * Applies the same visibility filters used by the LeftSidebar navigation
 * (OS, language, feature flags, browser) to prevent direct URL access
 * to routes that should be hidden in the current environment.
 *
 * Usage: wrap route groups in the router config:
 *   <Route path="/*" element={<RouteGuard />}>
 *     <Route path="settings" element={<Settings />} />
 *   </Route>
 */
const RouteGuard: React.FC = () => {
  const location = useLocation();
  const { os, isLoading: isOSLoading } = useOperatingSystem();
  const { flagValues, loading: featureFlagsLoading } = useFeatureFlags();

  const allRoutes: RouteProps[] = useMemo(() => Object.values(ROUTES), []);

  // Show a loading state while environment data is still being fetched
  if (isOSLoading || featureFlagsLoading) {
    return (
      <div data-testid="route-guard-loading" className="flex items-center justify-center h-full">
        Loading...
      </div>
    );
  }

  // Strip leading slashes for consistent comparison with route paths
  const currentPath = location.pathname.replace(/^\/+/, '');

  const allowed = isRouteAllowed(currentPath, allRoutes, {
    os,
    language: uiLanguage,
    browser: TARGET_BROWSER,
    featureFlags: flagValues,
  });

  if (!allowed) {
    return <Navigate to={`/${ROUTES.DASHBOARD.path}`} replace />;
  }

  return <Outlet />;
};

export default RouteGuard;
