import React from 'react';

interface ErrorMessageProps {
  error: string;
}

export const ErrorMessage: React.FC<ErrorMessageProps> = ({ error }) => {
  if (!error) return null;

  return (
    <div data-testid="div-23ca8118"  className="p-3 bg-danger-100 border border-danger-200 rounded-lg">
      <p data-testid="p-ba49f998"  className="text-danger text-sm">{error}</p>
    </div>
  );
};
