// ABOUTME: Pure feature flag logic, safe for both background and popup contexts.
// ABOUTME: Zero dependencies on DOM, React, or UI utilities.

import { chrome } from "@/utils/polyfill";
import { TARGET_BROWSER } from '@/app/scripts/browser-const';
import { BROWSER_NAME } from '@/app/scripts/app-consts.js';

/**
 * Determines if AI Scanner should be hidden based on availability, prod environment, and browser
 * Safe to call from both service worker (background) and popup contexts
 */
export const shouldHideAiScannerFeature = (isUnavailable: boolean = false): boolean => {
    if (
        typeof LanguageModel === 'undefined' || 
        TARGET_BROWSER as string === BROWSER_NAME.Firefox ||
        isUnavailable || 
        !chrome.runtime.getManifest().name.includes('Beta') ||
        !navigator?.language?.startsWith('en')
    ) {
        return true;
    }
    return false;
};
