
import React, { useState, useEffect } from 'react';
import { Card } from '$Popup/components/core/BGCard';
import BGSvgIcon from '$Popup/components/core/BGSvgIcon';
import BGButton from '$Popup/components/core/BGButton';
import { t } from '$Popup/i18n';
import { chrome } from '@/utils/polyfill';

/**
 * GrantAccessControlPermCard Component - Card to grant access control permissions
 * 
 * This component displays a card prompting the user to grant necessary permissions
 * for the Access Control feature to function properly.
 * 
 */

interface PermissionState {
  historyGranted: boolean;
  contentSettingsGranted: boolean;
}

interface GrantAccessControlPermCardProps {
  onPermissionStateChange?: (state: PermissionState) => void;
}

const GrantAccessControlPermCard: React.FC<GrantAccessControlPermCardProps> = ({ 
  onPermissionStateChange 
}) => {
  const [permissionState, setPermissionState] = useState<PermissionState>({
    historyGranted: false,
    contentSettingsGranted: false
  });
  const [isLoading, setIsLoading] = useState(true);

  // Check current permissions on component mount
  useEffect(() => {
    const checkPermissions = async () => {
      try {
        const historyGranted = await chrome.permissions.contains({
          permissions: ['history']
        });
        const contentSettingsGranted = await chrome.permissions.contains({
          permissions: ['contentSettings']
        });
        
        const newState = { historyGranted, contentSettingsGranted };
        setPermissionState(newState);
        onPermissionStateChange?.(newState);
      } catch (error) {
        console.error('Error checking permissions:', error);
      } finally {
        setIsLoading(false);
      }
    };

    checkPermissions();
  }, [onPermissionStateChange]);

  // Update permission state and notify parent
  const updatePermissionState = (updates: Partial<PermissionState>) => {
    const newState = { ...permissionState, ...updates };
    setPermissionState(newState);
    onPermissionStateChange?.(newState);
  };

  // Handle permission requests
  const handleAllowBrowsingHistoryAccess = async () => {
    try {
      const granted = await chrome.permissions.request({
        permissions: ['history']
      });
      if (granted) {
        console.log('Browsing history permission granted');
        updatePermissionState({ historyGranted: true });
      }
    } catch (error) {
      console.error('Error requesting browsing history permission:', error);
    }
  };

  const handleAllowContentSettingsAccess = async () => {
    try {
      const granted = await chrome.permissions.request({
        permissions: ['contentSettings']
      });
      if (granted) {
        console.log('Content settings permission granted');
        updatePermissionState({ contentSettingsGranted: true });
      }
    } catch (error) {
      console.error('Error requesting content settings permission:', error);
    }
  };

  // Render permission button or success state
  const renderPermissionControl = (isGranted: boolean, onAllow: () => void) => {
    if (isLoading) {
      return (
        <BGButton
          variant="primary"
          size="default"
          disabled={true}
          loading={true}
          className="w-fit px-7 py-5"
        >
          Loading...
        </BGButton>
      );
    }

    if (isGranted) {
      return (
        <div data-testid="div-280afd32"  className="flex items-center gap-2 text-success font-medium w-fit px-5">
          <BGSvgIcon iconName="simple-green-check" size={25} />
          <span data-testid="span-ec49b500"  className='text-sm'>{t('allowedPermissionBtnTxt')}</span>
        </div>
      );
    }

    return (
      <BGButton
        variant="primary"
        size="default"
        onClick={onAllow}
        className="w-fit px-7 py-5"
      >
        {t('allowAccessButton')}
      </BGButton>
    );
  };

  return (
    <Card className="bg-backdrop border-tragic-200">
      <div data-testid="div-f13d7f6c" className="flex flex-col gap-6">
        {/* Header Section */}
        <div data-testid="div-98780dc8" className="flex items-center gap-4">
          <div data-testid="div-d97a8c9e" className="shrink-0">
            <BGSvgIcon iconName="clipboard-protection" size={70} />
          </div>
          <div data-testid="div-8ecfaa0e" className="flex-1">
            <h3 data-testid="h3-175dca70" className="text-xl font-medium text-tragic mb-2">
              {t('accessControlPermissionNeededTitle')}
            </h3>
            <p data-testid="p-1f97d6b1" className="text-tragic-400 text-base">
              {t('accessControlPermissionNeededDescription')}
            </p>
          </div>
        </div>

        {/* Permission Sections */}
        <div data-testid="div-bcbe0795" className="space-y-6 rounded-2xl bg-tragic-100 p-6">
          {/* Browsing History Permission */}
          <div data-testid="div-8602cbed" className="flex justify-between items-center gap-4">
            <div data-testid="div-a5aaa9d5" className="flex-1">
              <h4 data-testid="h4-41271fa3" className="text-lg font-medium text-tragic mb-2">
                {t('accessControlBrowsingHistoryTitle')}
              </h4>
              <p data-testid="p-26062c41" className="text-tragic-400 text-sm w-9/10">
                {t('accessControlBrowsingHistoryDescription')}
              </p>
            </div>
            <div data-testid="div-2758f8e3" className="flex items-center justify-center">
              {renderPermissionControl(permissionState.historyGranted, handleAllowBrowsingHistoryAccess)}
            </div>
          </div>

          {/* Divider */}
          <hr className="border-t border-tragic-200" />
          
          {/* Content Settings Permission */}
          <div data-testid="div-4e30730e" className="flex justify-between items-center gap-4">
            <div data-testid="div-a628b7c0" className="flex-1">
              <h4 data-testid="h4-cf457fde" className="text-lg font-medium text-tragic mb-2">
                {t('accessControlContentSettingsTitle')}
              </h4>
              <p data-testid="p-dbeefe9b" className="text-tragic-400 text-sm w-9/10">
                {t('accessControlContentSettingsDescription')}
              </p>
            </div>
            <div data-testid="div-92f9ab9e" className="flex items-center justify-center">
              {renderPermissionControl(permissionState.contentSettingsGranted, handleAllowContentSettingsAccess)}
            </div>
          </div>
        </div>
      </div>
    </Card>
  );
};

export default GrantAccessControlPermCard;