import type { DetectionRow } from './types';

// Raw detection data from background script
export interface RawDetectionItem {
  site: string;
  type: 'malware' | 'scam' | 'content';
  subtype: string;
  date: number; // timestamp
}

/**
 * Validates if a detection item has all required fields
 */
export const hasValidValues = (item: any): item is RawDetectionItem => {
  const keysToVerify = ['site', 'type', 'subtype', 'date'];
  return keysToVerify.every((key) => Object.prototype.hasOwnProperty.call(item, key));
};

/**
 * Transforms raw detection data from background script to table format
 */
export const transformDetectionItem = (item: RawDetectionItem): DetectionRow => {
  // Format the date like the original: "MMM d, yyyy. HH:mm"
  const readableDate = new Date(item.date).toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }).replace(',', '. ').replace(' at ', '. ');

  // Format subtype like the original: convert camelCase to readable text
  const formattedSubtype = item.subtype
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .toLowerCase();

  return {
    id: item.date.toString(), // Use timestamp as unique ID
    siteUrl: item.site,
    type: formattedSubtype,
    date: readableDate,
    // Store original data for delete operations and filtering
    _raw: {
      hostData: item.site,
      rowId: item.date.toString(),
      type: item.type, // Store original type for filtering
      subtype: item.subtype
    }
  };
};
