import { useState, useEffect } from 'react';
import { t, getCurrentLanguage, getAcceptLanguages } from './index';

/**
 * React hook for using translations in components
 * Provides reactive translation function and current language
 */
export const useTranslation = () => {
  const [language, setLanguage] = useState(getCurrentLanguage());

  useEffect(() => {
    // Update language if it changes (though rare in Chrome extensions)
    setLanguage(getCurrentLanguage());
  }, []);

  return {
    t,
    language,
    getCurrentLanguage
  };
};

/**
 * React hook for getting accept languages
 * Useful for language selection interfaces
 */
export const useAcceptLanguages = () => {
  const [languages, setLanguages] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getAcceptLanguages().then((langs) => {
      setLanguages(langs);
      setLoading(false);
    });
  }, []);

  return {
    languages,
    loading
  };
};
