import BGSvgIcon from '../core/BGSvgIcon'
import { cn } from '$Popup/lib/utils'
import { t } from '$Popup/i18n'

export type Option = {
  value: string;
  label: string;
  iconName: string;
};

export function SegmentedFilters({
  value,
  onChange,
  options,
}: {
  value: string
  onChange: (val: string) => void
  options: Option[]
}) {
  return (
    <div data-testid="div-bd1354a3" 
      className="flex items-center gap-4"
      role="radiogroup"
      aria-label="Filters"
    >
      {options.map(({ value: v, label, iconName }, index) => {
        const selected = value === v

        return (
          <button data-testid={`button-d9d64d26-${index}`}
            key={v}
            type="button"
            role="radio"
            aria-checked={selected}
            onClick={() => onChange(v)}
            className={cn(
              'inline-flex items-center justify-center gap-3',
              'rounded-full px-6 py-2',
              'font-medium transition-colors',
              selected
                ? 'bg-selected-chip-liteblue text-selected-chip'
                : 'bg-chip-liteblue'
            )}
          >
            {/* if dark mode, make icon colour red */}

            <BGSvgIcon iconName={iconName} size={16} forceFill={selected ? 'selected-chip' : 'chip-icon'} />
            <span data-testid="span-8ddd1a7e" >{t(label)}</span>
          </button>
        )
      })}
    </div>
  )
}
