import {
  EXCLUSION_ADS,
  EXCLUSION_MALWARE,
  EXCLUSION_SCAMS
} from "@/app/scripts/app-consts";

export interface Website {
  domain: string;
  exclusions: number[];
}

export interface ExclusionOption {
  value: number;
  constantKey: string;
  humanReadable: string;
}

// Constants for exclusion options (matching app-consts.js)
export const ALLOWED_EXCLUSION_OPTIONS: ExclusionOption[] = [
  { value: 2, constantKey: EXCLUSION_ADS, humanReadable: 'Ads / Trackers' },
  { value: 4, constantKey: EXCLUSION_MALWARE, humanReadable: 'Malware' },
  { value: 6, constantKey: EXCLUSION_SCAMS, humanReadable: 'Scams' }
];

/**
 * Translates machine-readable exclusion data to human-readable format
 */
export const translateExclusionToHumanReadable = (machineReadable: number[] | string): string => {
  const allowedOptions: string[] = [];
  
  if (Array.isArray(machineReadable)) {
    machineReadable.forEach((allowedValue) => {
      const readableValue = ALLOWED_EXCLUSION_OPTIONS.find((option) => option.value === allowedValue);
      if (readableValue) {
        allowedOptions.push(readableValue.humanReadable);
      }
    });
  } else if (typeof machineReadable === 'string') {
    const exclusions = machineReadable.split(",");
    exclusions.forEach((allowedKey) => {
      const readableValue = ALLOWED_EXCLUSION_OPTIONS.find((option) => option.constantKey === allowedKey);
      if (readableValue) {
        allowedOptions.push(readableValue.humanReadable);
      }
    });
  }
  
  return allowedOptions.join(', ');
};

/**
 * Checks if an array has valid allow values
 */
export const hasValidAllows = (arr: unknown[]): boolean => {
  if (!Array.isArray(arr) || arr.length === 0) return false;
  
  return arr.some(element => typeof element === 'number' && element > 0);
};

/**
 * Transforms raw allow list response data into Website objects
 */
export const transformAllowListData = (responseData: Record<string, unknown[]>): Website[] => {
  const websiteList: Website[] = [];
  
  for (const host in responseData) {
    if (Object.hasOwnProperty.call(responseData, host)) {
      if (hasValidAllows(responseData[host])) {
        websiteList.push({
          domain: host,
          exclusions: responseData[host] as number[]
        });
      }
    }
  }
  
  return websiteList;
};

// Special marker for delete all operations
export const DELETE_ALL_MARKER = 'ALL_WEBSITES';