import { handleAiScannerButtonClick, shouldHideAiScannerFeature } from '@/app/popup/src/components/InjectableComponents/AiScanner/logic';
import { useLanguageModelAvailability } from '@/app/popup/src/components/InjectableComponents/AiScanner/hooks';
import BGSvgIcon from '$Popup/components/core/BGSvgIcon';
import { useIsValidTab } from '$Popup/utils/tabData';
import { useGeneralSettings, useDismissAiScannerPopover } from '$Popup/store';
import React from "react";
import { BGPopover } from '$Popup/components/core';

export const AiScannerPopupShieldBtn: React.FC = () => {
    const isValidTab = useIsValidTab();
    const { hasSeenAiScannerPopover } = useGeneralSettings();
    const dismissAiScannerPopover = useDismissAiScannerPopover();
    const { isReadyToUse, needsDownload, isDownloading, isUnavailable } = useLanguageModelAvailability();

    if (shouldHideAiScannerFeature(isUnavailable)) {
        return null;
    }

    const handleClick = () => handleAiScannerButtonClick(isReadyToUse, needsDownload, isDownloading);

    // if the current tab is not valid for scanning, make the button semi-transparent and non-clickable
    return (
        <div data-testid="div-8c4e7d37" className='relative'>
            {isValidTab ?
                // Persistent mode — stays until closed
                <BGPopover
                    trigger={
                        <button data-testid="button-888bd110" onClick={handleClick}>
                            <BGSvgIcon iconName="ai-scanner-shield" size={25} alt="Ai Scanner Shield" />
                            {/* Show download icon only when model needs download */}
                            {needsDownload && (
                                <BGSvgIcon
                                    iconName="download-circle"
                                    size={22}
                                    alt="Gemini Nano Download Circle"
                                    className="absolute -bottom-2.5 -right-3"
                                />
                            )}
                            {isDownloading && (
                                <BGSvgIcon
                                    iconName="loading-dots-circle"
                                    size={22}
                                    alt="Gemini Nano Download Circle"
                                    className="absolute -bottom-2.5 -right-3 animate-spin"
                                />
                            )}
                        </button>
                    }
                    className='w-36 -right-5!'
                    arrowOffset='calc(100% - 2.5rem)'
                    position="bottom"
                    align="end"
                    hasCloseBtn
                    visible={!hasSeenAiScannerPopover}
                    onClose={() => dismissAiScannerPopover()}
                >
                    <h5 data-testid="h5-dc26af69" className='text-backdrop font-normal text-base mb-1'>Scam Guard</h5>
                    <p data-testid="p-03fc9900" className='text-backdrop font-light text-sm leading-5'>Real-time scam detection with AI</p>
                </BGPopover>
                :
                <button data-testid="button-51a16ad9" disabled className="opacity-35 cursor-not-allowed">
                    <BGSvgIcon iconName="ai-scanner-shield" size={25} alt="Ai Scanner Shield" />
                </button>
            }
        </div>
    );
};
