import * as React from "react";
import { DataTable, TableEmptyState } from "$Popup/components/core/BGTable";
import DeleteDetectionConfirmModal from "../DeleteConfirmModal";
import { useDetectionHistory } from "./hooks";
import { createColumns } from "./columns";
import type { DetectionHistoryTableProps, DetectionRow } from "./types";
import { t } from "$Popup/i18n";

const DetectionHistoryTable: React.FC<DetectionHistoryTableProps> = ({ 
  filterType 
}) => {
  const {
    detections,
    loading,
    deleteModal,
    openDeleteModal,
    openDeleteAllModal,
    closeDeleteModal,
    confirmDelete
  } = useDetectionHistory();

  // Filter detections based on the selected filter type
  const filteredDetections = React.useMemo(() => {
    if (!filterType) {
      return detections; // Show all if no filter selected
    }
    
    return detections.filter(detection => {
      // Match filter type with the original detection type from raw data
      // Use only the canonical _raw.type for filtering to ensure precision
      const normalizedFilterType = filterType === 'scams' ? 'scam' : filterType;
      return detection._raw?.type === normalizedFilterType;
    });
  }, [detections, filterType]);

  const handleDeleteAllClick = React.useCallback(() => {
    openDeleteAllModal();
  }, [openDeleteAllModal]);

  const handleRemoveDetection = React.useCallback((detection: DetectionRow) => {
    openDeleteModal(detection);
  }, [openDeleteModal]);

  const columns = createColumns(filteredDetections, handleDeleteAllClick, handleRemoveDetection);

  if (loading) {
    return (
      <div data-testid="div-3210ae30"  className="flex justify-center items-center py-8">
        <span data-testid="span-ed077755" >{t("Loading")}</span>
      </div>
    );
  }

  return (
    <>
      <div data-testid="div-99c830fb"  className="w-full">
        <DataTable 
          columns={columns} 
          data={filteredDetections} 
          emptyState={
            <TableEmptyState 
              title={t('NoDetectionsFoundTitle')}
              description={t('NoDetectionsFoundDescription')}
            />
          }
          enableSearch={true}
          searchPlaceholder="Search detections..."
        />
      </div>

      <DeleteDetectionConfirmModal
        isOpen={deleteModal.isOpen}
        onClose={closeDeleteModal}
        onConfirm={confirmDelete}
        loading={deleteModal.isDeleting}
        detectionSite={deleteModal.isDeleteAll ? undefined : deleteModal.detectionToDelete?.siteUrl}
      />
    </>
  );
};

export default DetectionHistoryTable;
