import { SETTING_ADS, SETTING_SCAMS, SETTING_MALWARE} from '@/app/scripts/app-consts';
import { OS_KEYS } from '$Popup/types/consts';
import type { RouteProps } from '$Popup/routes/types';

// Special constant for protected websites feature (premium-only feature)
// Shows as LOCKED for non-premium users, ON for premium users
export const SETTING_CONTENT_PROTECTION = 'protectedContent' as const;

export interface ProtectionItem {
    iconName: string;
    labelKey: string;
    status: 'OFF' | 'ON' | 'LOCKED';
    storeKey: typeof SETTING_ADS | typeof SETTING_MALWARE | typeof SETTING_SCAMS | typeof SETTING_CONTENT_PROTECTION;
    relatedFeatureRoute?: RouteProps;
}

export interface ProtectionStatus {
    iconName: string;
    statusText: string;
    statusClass: string;
}

export interface ProtectionConfig {
    labelKey: string;
    iconName: string;
    storeKey: typeof SETTING_ADS | typeof SETTING_MALWARE | typeof SETTING_SCAMS | typeof SETTING_CONTENT_PROTECTION;
    showOs?: Array<typeof OS_KEYS[keyof typeof OS_KEYS]>;
    relatedFeatureRoute?: RouteProps;
}
