// Types for the general settings store
export interface GeneralSettings {
  enableProtection: boolean;
  enableProtectionAds: boolean;
  enableProtectionScams: boolean;
  enableProtectionMalware: boolean;
  enableProtectionGtld: boolean;
  enableShowBlockCount: boolean;
  enableMonthlyNotification: boolean;
  enableMaliciousNotification: boolean;
  enableNewReleaseNotification: boolean;
  enableProfileCheckerNotification: boolean;
  enableBlockCountDisplay: boolean;
  enableSkimmerProtection: boolean;
  enableBreachNotification: boolean;
  enableSearchHijackingNotification: boolean;
  enableVerboseLogging: boolean;
  enableClipboardReadPermission: boolean;
  enablePrivacyPermission: boolean;
  hasSeenAiScannerPopover: boolean;
  isLoading: boolean;
}

export interface GeneralSettingsActions {
  setGeneralSetting: <K extends keyof GeneralSettings>(
    key: K,
    value: GeneralSettings[K]
  ) => void
  toggleGeneralProtection: () => Promise<void>
  toggleGeneralProtectionLayer: (
    layer: keyof Omit<GeneralSettings, "enableProtection" | "enableClipboardReadPermission" | "enablePrivacyPermission">
  ) => Promise<void>;
  toggleClipboardPermission: () => Promise<void>;
  togglePrivacyPermission: () => Promise<void>;
  loadGeneralSettings: () => Promise<void>;
  dismissAiScannerPopover: () => Promise<void>;
}

// Combined general settings slice interface
export interface GeneralSettingsSlice
  extends GeneralSettings,
    GeneralSettingsActions {}

// Default values
export const DEFAULT_GENERAL_SETTINGS: GeneralSettings = {
  enableBlockCountDisplay: true,
  enableBreachNotification: true,
  enableClipboardReadPermission: false,
  enablePrivacyPermission: false,
  enableMaliciousNotification: true,
  enableMonthlyNotification: true,
  enableNewReleaseNotification: true,
  enableProtection: true,
  enableProtectionAds: true,
  enableProtectionGtld: false,
  enableProtectionMalware: true,
  enableProtectionScams: true,
  enableSearchHijackingNotification: true,
  enableProfileCheckerNotification: true,
  enableShowBlockCount: true,
  enableSkimmerProtection: true,
  enableVerboseLogging: false,
  hasSeenAiScannerPopover: true, // Default to true (hidden) to prevent flicker on load
  isLoading: true,
};

// Tab-related types
export interface SiteInfo {
  url: string
  host: string
  sld: string
  domains: string[]
  friendlyUrl: string
}

export interface HistoryEntry {
  url: string
  timestamp: number
}

export interface TabMeta {
  history: HistoryEntry[]
  timestamp: number
}

export interface BlockedTotals {
  ads: number
  malware: number
  scams: number
  content: number
}

export interface BlockedByDomain {
  [domain: string]: {
    [source: string]: number
  }
}

export interface BlockedDetails {
  ads: BlockedByDomain
  malware: BlockedByDomain
  scams: BlockedByDomain
  content: BlockedByDomain
}

export interface BlockedData {
  totals: BlockedTotals
  ads: BlockedByDomain
  malware: BlockedByDomain
  scams: BlockedByDomain
  content: BlockedByDomain
}

export interface TabData {
  tabId: number
  site: SiteInfo
  status: string
  meta: TabMeta
  blocked: BlockedData
  blockedHistory: BlockedData
}

export interface TabsData {
  [tabId: string]: TabData
}

export interface TabSlice {
  // State
  tabsData: TabsData
  currentTabId: number | null
  isLoading: boolean

  // Actions
  setTabData: (tabId: number, tabData: TabData) => void
  updateTabBlocked: (tabId: number, blocked: BlockedData) => void
  setCurrentTabId: (tabId: number | null) => void
  getCurrentTabData: () => TabData | null
  loadTabsData: () => Promise<void>
  clearTabData: (tabId?: number) => void
}

export const DEFAULT_BLOCKED_TOTALS: BlockedTotals = {
  ads: 0,
  malware: 0,
  scams: 0,
  content: 0,
}

export const DEFAULT_BLOCKED_DATA: BlockedData = {
  totals: DEFAULT_BLOCKED_TOTALS,
  ads: {},
  malware: {},
  scams: {},
  content: {},
}

// Site protection settings types
export interface SiteProtectionSettings {
  ads: boolean // Protection ON/OFF for ads on this site
  scams: boolean // Protection ON/OFF for scams on this site
  malware: boolean // Protection ON/OFF for malware on this site
}

export interface SiteProtections {
  [hostname: string]: SiteProtectionSettings
}

export interface SiteProtectionSlice {
  // State
  siteProtections: SiteProtections
  isLoading: boolean
  showTutorial: boolean
  // Actions
  initShowTutorial: () => Promise<void>
  setShowTutorialDone: () => Promise<void>
  setSiteProtections: (protections: SiteProtections) => void
  toggleSiteProtection: (
    hostname: string,
    protectionType: keyof SiteProtectionSettings
  ) => Promise<boolean>
  isSiteProtected: (
    hostname: string,
    protectionType: keyof SiteProtectionSettings
  ) => boolean
  getSiteProtections: (hostname: string) => SiteProtectionSettings
  loadSiteProtections: (hostname: string) => Promise<void>
  clearAllSiteProtections: () => Promise<void>
}

export const DEFAULT_SITE_PROTECTION_SETTINGS: SiteProtectionSettings = {
  ads: true, // true = protection ON
  scams: true, // true = protection ON
  malware: true, // true = protection ON
}

export interface BlockedItem {
  domain: string
  blockUrls: string[]
  xpath: string
}

export interface BlockedItemsByDomain {
  [domain: string]: Array<{ blockUrls: string[]; xpath: string }>
}

export interface BlockedItemsState {
  blockedItemsByDomain: BlockedItemsByDomain
  isLoading: boolean
  error?: string | null
  currentBlockItem?: BlockedItem | null
}

export interface BlockedItemsActions {
  loadBlockedItems: () => Promise<void>
  setCurrentBlockItem: (item: BlockedItem | null) => void
  deleteBlockedItem: (item: BlockedItem) => Promise<boolean>
  deleteAllBlockedItems: () => Promise<boolean>
  getAllItems: () => BlockedItem[]
}

export interface BlockedItemsSlice
  extends BlockedItemsState,
    BlockedItemsActions {}

export const DEFAULT_BLOCKED_ITEMS_STATE: BlockedItemsState = {
  blockedItemsByDomain: {},
  isLoading: false,
  error: null,
  currentBlockItem: null,
}
