import * as React from "react";
import { BGModal } from "$Popup/components/core/BGModal/BGModal";
import { useAddContentControlForm } from "./useAddContentControlForm";
import { UrlInput } from "./UrlInput";
import { ErrorMessage } from "./ErrorMessage";
import { ActionButtons } from "./ActionButtons";
import { t } from "$Popup/i18n";
import type { AddContentControlModalProps } from "./types";

const AddContentControlModal: React.FC<AddContentControlModalProps> = ({ isOpen, onClose, onSuccess }) => {
  const { formState, actions, computed } = useAddContentControlForm(onSuccess, onClose);

  const handleClose = () => {
    actions.resetForm();
    onClose();
  };

  return (
    <BGModal
      isOpen={isOpen}
      onClose={handleClose}
      title={t("contentControlWindowTitle")}
      className="max-w-md"
    >
      <div data-testid="div-aea091e2"  className="space-y-6">
        <UrlInput
          value={formState.url}
          onChange={actions.setUrl}
          isValid={formState.isValidUrl}
          disabled={formState.loading}
        />

        <ErrorMessage error={formState.error} />

        <ActionButtons
          onCancel={handleClose}
          onSubmit={actions.submitForm}
          canSubmit={computed.canSubmit}
          loading={formState.loading}
        />
      </div>
    </BGModal>
  );
};

export default AddContentControlModal;
