import React, { useEffect, useMemo } from 'react';
import {
  BGButton,
  BGCheckBox,
  BGSvgIcon,
  Card,
  BGBanner,
} from '$Popup/components/core';
import { EXTERNAL_LINKS } from '$Popup/constants/links';
import { t } from '$Popup/i18n';
import { chrome } from '@/utils/polyfill';
import { humanReadableSubType, useBlockPage } from './hooks/useBlockPage';
import UpgradeCard from '$Popup/components/Layout/UpgradeCard';

const BlockPage: React.FC = () => {
  const {
    continueAlways,
    setContinueAlways,
    initFromActiveTab,
    continueToSite,
    goBack,
    blockedHost,
    blockedType,
    blockedSubtype,
    dbVersion: dbVersionZustand,
    ruleId,
  } = useBlockPage();

  useEffect(() => {
    initFromActiveTab();
  }, [initFromActiveTab]);

  const blockReasonType = humanReadableSubType(blockedSubtype, blockedType);

  const appVersion = useMemo(() => chrome.runtime.getManifest().version, []);

  const isAdsTracker = useMemo(() => {
    return (
      (blockedType === 'ad' || blockedType === 'ads') &&
      blockedSubtype === 'adserver'
    );
  }, [blockedType, blockedSubtype]);

  const versionLine = useMemo(() => {
    const heuristics = `Heuristics: ${blockReasonType}`;
    const db = dbVersionZustand == null ? heuristics : dbVersionZustand;
    return `v${appVersion} | ${db}${ruleId ? ` | ID: ${ruleId}` : ''}`;
  }, [appVersion, blockReasonType, dbVersionZustand, ruleId]);

  return (
    <div data-testid="div-c3ca13fe" >
      <div data-testid="div-3102050d"  className="flex flex-col mx-auto max-w-4xl px-4 py-8 gap-4">
        <div data-testid="div-5de09c15"  className="title-large ">
          {t('blockedByTitle', blockReasonType)}
        </div>
        <div data-testid="div-c9efd5be"  className="title-medium font-normal text-[14px]">
          {isAdsTracker
            ? t('mv3WebsiteTrackerBlockExplanation')
            : t('mv3WebsiteBlockExplanation')}
        </div>
        <Card className="flex flex-col py-8 px-[79px] items-center justify-center gap-6">
          <div data-testid="div-e5bd5719"  className="flex flex-col items-center justify-center ">
            <BGSvgIcon
              iconName='blocked'
              size={150}
            />

            <div data-testid="div-cfe5446c"  className={' title-medium text-[14px] font-medium '}>
              {`${t('mv3WebsiteBlockHeader')}: ${blockedHost}`}
            </div>

            <p data-testid="p-c78232d8"  className="text-mb-text-secondary mt-1">{versionLine}</p>
          </div>
          <BGBanner variant={isAdsTracker ? 'lowrisk' : 'highrisk'}>
            <p data-testid="p-07175e77" >
              {isAdsTracker
                ? t('mv3WebsiteTrackerBlockAlert')
                : t('mv3WebsiteBlockAlert')}{' '}
              <a data-testid="a-afb728c9" 
                className={'text-primary font-medium cursor-pointer'}
                href={EXTERNAL_LINKS.support}
                target={'_blank'}
                rel={'noreferrer'}
              >
                {t('mv3WebsiteBlockMalwarebytesSupport')}
              </a>{' '}
            </p>
          </BGBanner>
          <BGButton size="large" variant={'primary'} onClick={goBack}>
            <div data-testid="div-99bba902"  className={'flex flex-row items-center justify-center gap-2 '}>
              <BGSvgIcon iconName={'back-arrow'} size={18} />
              {t('mv3WebsiteBlockGoBack')}
            </div>
          </BGButton>
          <div data-testid="div-ce4c1150"  className={'flex flex-col items-center justify-center gap-4'}>
            <BGButton variant="secondary" size="large" onClick={continueToSite}>
              {t('mv3WebsiteBlockContinue')}
            </BGButton>
            <div data-testid="div-634a44ac"  className="flex flex-row items-start gap-2 ">
              <div data-testid="div-19c3d77d" >
                <BGCheckBox
                  checked={continueAlways}
                  onCheckedChange={(val) => setContinueAlways(Boolean(val))}
                  className=''
                />
              </div>
              <p data-testid="p-6e8036c3"  className="text-left ">{t('mv3WebsiteBlockContinueAlways')}</p>
            </div>
          </div>
        </Card>
        <UpgradeCard className="bg-transparent" externalLink={EXTERNAL_LINKS.upsellCardFromBlockPage} />
      </div>
    </div>
  );
};

export default BlockPage;
