// ABOUTME: Custom hook for handling Browser Guard settings export functionality
// ABOUTME: Manages export configuration, processes data, and downloads export files
import { useState, useCallback } from 'react'
import { BROWSER_NAME, MSG_EXPORT_SETTINGS } from '@/app/scripts/app-consts'
import { chrome } from '@/utils/polyfill'
import { TARGET_BROWSER } from '@/app/scripts/browser-const'
import { t } from "$Popup/i18n";

interface ExportConfig {
  'allow-list': boolean
  'blocked-items': boolean
  'content-control': boolean
  'settings': boolean
}

interface UseExportSettingsReturn {
  isExporting: boolean
  exportError: string | null
  exportSuccess: boolean
  exportSettings: (config: ExportConfig) => Promise<void>
  clearStatus: () => void
}

const sleep = (ms: number): Promise<void> => {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

const generateExportData = async (config: ExportConfig): Promise<any> => {
  return new Promise((resolve, reject) => {
    chrome.runtime.sendMessage(
      { type: MSG_EXPORT_SETTINGS, config },
      (response) => {
        if (!response || response.error || chrome.runtime.lastError) {
          console.error('INC_EXP: Failed to export settings', {
            error: (response ? response.error : null) || chrome.runtime.lastError
          })
          reject((response ? response.error : null) || chrome.runtime.lastError)
        } else {
          console.log('INC_EXP: Successfully exported settings')
          resolve(response.data)
        }
      }
    )
  })
}

const downloadExportDataToFile = (exportDataStr: string): void => {
  let dlDownloadName = 'BG-Export'
  const url = URL.createObjectURL(
    new Blob([exportDataStr], { type: 'application/json' })
  )
  console.log('INC_EXP: Generated export file', url)
  
  const time = new Date()
  dlDownloadName = `BG-Export_v${chrome.runtime.getManifest().version}_` +
    `${time.toISOString().slice(0, 10)}_${time.getHours()}${time.getMinutes()}${time.getSeconds()}.json`
  
  console.log('INC_EXP: Downloading export file', { dlDownloadName, url })
  const dl = chrome.downloads.download({ url, filename: dlDownloadName })

  const revokeURL = () => {
    if ((TARGET_BROWSER as string) !== BROWSER_NAME.Firefox) {
      // revoking the URL makes the download inaccessible in firefox
      URL.revokeObjectURL(url)
    }
  }

  if (dl) {
    dl.then(
      () => revokeURL(),
      () => revokeURL()
    )
  }
  console.log('INC_EXP: Successfully Downloaded export file')
}

export const useExportSettings = (): UseExportSettingsReturn => {
  const [isExporting, setIsExporting] = useState(false)
  const [exportError, setExportError] = useState<string | null>(null)
  const [exportSuccess, setExportSuccess] = useState(false)

  const clearStatus = useCallback(() => {
    setExportError(null)
    setExportSuccess(false)
  }, [])

  const exportSettings = useCallback(async (config: ExportConfig) => {
    try {
      setIsExporting(true)
      setExportError(null)
      setExportSuccess(false)
      
      console.debug('INC_EXP: Exporting Data', config)
      
      // 2-second artificial delay for UX improvement (from original code)
      await sleep(2000)
      
      const exportData = await generateExportData(config)
      downloadExportDataToFile(JSON.stringify(exportData))
      setExportSuccess(true)
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : t('exportError')
      console.error('INC_EXP: Export failed', err)
      setExportError(errorMsg)
    } finally {
      setIsExporting(false)
    }
  }, [])

  return {
    isExporting,
    exportError,
    exportSuccess,
    exportSettings,
    clearStatus
  }
}