import { useMemo } from 'react';
import { t } from "$Popup/i18n";
import { 
  usePremiumStatus, 
  useNativeHostStatus, 
  usePremiumLicenseState, 
  usePrivacyLicenseState,
  hasPremiumAccess,
  hasVpnAccess 
} from '$Popup/utils/general';
import { ProtectionCardData, StatusVariant } from '$Popup/types/protection';
import { protectionCards } from './cards';

export interface CardStatus {
  statusText: string;
  statusVariant: StatusVariant;
  btnText: string;
  isLoading: boolean;
}

/**
 * Custom hook that provides dynamic card status based on user's premium and VPN access
 * Replicates the logic from legacy include-upsell.js
 */
export const useProtectionCardStatus = () => {
  const { isPremium, isPremiumLoading } = usePremiumStatus();
  const { isConnected: isNHConnected, isLoading: isNHLoading } = useNativeHostStatus();
  const { licenseState: premiumLicenseState, isLoading: isPremiumLicenseLoading } = usePremiumLicenseState();
  const { licenseState: privacyLicenseState, isLoading: isPrivacyLicenseLoading } = usePrivacyLicenseState();

  const isLoading = isPremiumLoading || isNHLoading || isPremiumLicenseLoading || isPrivacyLicenseLoading;

  // Calculate premium security card status
  const premiumSecurityStatus = useMemo((): CardStatus => {
    if (isLoading) {
      return {
        statusText: `${t('CheckingStatus')}...`,
        statusVariant: 'info',
        btnText: `${t('Loading')}...`,
        isLoading: true
      };
    }

    // If native host is not connected, show install prompt
    if (!isNHConnected) {
      return {
        statusText: t('NotInstalled'),
        statusVariant: 'warning',
        btnText: t('InstallFreeProtection'),
        isLoading: false
      };
    }

    // If user has premium access, show installed status
    if (hasPremiumAccess(isPremium, premiumLicenseState)) {
      return {
        statusText: t('Installed'),
        statusVariant: 'success',
        btnText: t('LearnMoreText'),
        isLoading: false
      };
    }

    // Free user with native host connected
    return {
      statusText: t('FreeVersionInstalled'),
      statusVariant: 'warning',
      btnText: t('UpgradeToPremium'),
      isLoading: false
    };
  }, [isLoading, isNHConnected, isPremium, premiumLicenseState]);

  // Calculate VPN card status
  const vpnStatus = useMemo((): CardStatus => {
    if (isLoading) {
      return {
        statusText: `${t('CheckingStatus')}...`,
        statusVariant: 'info',
        btnText: `${t('Loading')}...`,
        isLoading: true
      };
    }

    // If native host is not connected, show install prompt
    if (!isNHConnected) {
      return {
        statusText: `${t('NotInstalled')}`,
        statusVariant: 'warning',
        btnText: t('InstallVPN'),
        isLoading: false
      };
    }

    // If user has both premium and VPN access, show installed status
    if (hasVpnAccess(isPremium, premiumLicenseState, privacyLicenseState)) {
      return {
        statusText: t('Installed'),
        statusVariant: 'success',
        btnText: t('LearnMoreText'),
        isLoading: false
      };
    }

    // Free user or premium without VPN license
    return {
      statusText: t('NotIncludedInYourSubscription'),
      statusVariant: 'warning',
      btnText: t('UpgradeToGetVPN'),
      isLoading: false
    };
  }, [isLoading, isNHConnected, isPremium, premiumLicenseState, privacyLicenseState]);

  // Generate dynamic cards with status
  const dynamicCards = useMemo((): ProtectionCardData[] => {
    return protectionCards.map((card) => {
      let cardStatus: CardStatus;
      
      switch (card.id) {
        case 'premium-security-card':
          cardStatus = premiumSecurityStatus;
          break;
        case 'privacy-vpn-card':
          cardStatus = vpnStatus;
          break;
        default:
          cardStatus = {
            statusText: card.statusText,
            statusVariant: card.statusVariant,
            btnText: card.btnText,
            isLoading: false
          };
      }

      return {
        ...card,
        statusText: cardStatus.statusText,
        statusVariant: cardStatus.statusVariant,
        btnText: cardStatus.btnText
      };
    });
  }, [premiumSecurityStatus, vpnStatus]);

  return {
    cards: dynamicCards,
    isLoading,
    premiumSecurityStatus,
    vpnStatus
  };
};
