import BGSvgIcon from '$Popup/components/core/BGSvgIcon';
import AllowListTable from '$Popup/components/AllowList/AllowListTable';
import AddAllowModal from '$Popup/components/AllowList/AddAllowModal';
import { useModal } from '$Popup/components/core';
import { t } from '$Popup/i18n';
import { useState } from 'react';

const AllowList: React.FC = () => {
    const addModal = useModal();
    const [refreshKey, setRefreshKey] = useState(0);

    const handleAddSuccess = () => {
        // Refresh the table data by incrementing the key
        setRefreshKey(prev => prev + 1);
    };

    return (
        <div data-testid="div-fb1e0654"  className="AllowList mx-auto flex flex-col gap-4">
            {/* Header */}
            <div data-testid="div-846d12bf"  className={"flex w-full justify-between items-center "}>
                <div data-testid="div-4e25c347"  className={"flex flex-col space-y-2 "}>
                    <h3 data-testid="h3-57b1ba0a" >{t("AllowListTitle")}</h3>
                    <p data-testid="p-4a003ae3" >{t("AllowListDescription")}</p>
                </div>
                <button data-testid="button-59c3dd19"  
                    onClick={addModal.openModal}
                    className="flex items-center bg-primary hover:bg-primary-hover h-fit rounded-4xl text-backdrop text-sm py-2.5 px-6 pl-5 min-w-[fit-content]"
                >
                    <BGSvgIcon iconName="white-add" size={16} className="mr-2" />
                    {t("AddWebsiteButton")}
                </button>
            </div>
            {/* Allow List Table */}
            <AllowListTable refreshKey={refreshKey} />

            {/* Add Allow Modal */}
            <AddAllowModal
                isOpen={addModal.isOpen}
                onClose={addModal.closeModal}
                onSuccess={handleAddSuccess}
            />
        </div>
    );
}
export default AllowList;