import { useEffect, useState } from 'react';
import type { ChromeRuntimeMessage, ChromeRuntimeResponse, UseNativeMessagingReturn } from './types';
import { chrome } from "@/utils/polyfill";

/**
 * Message types for Chrome extension communication
 */
const MSG_IS_NEEDING_NATIVE_MSG = 'MSG_IS_NEEDING_NATIVE_MSG';
const MSG_SETTINGS_SET = 'MSG_SETTINGS_SET';
const SETTING_NATIVE_MESSAGING = 'SETTING_NATIVE_MESSAGING';

/**
 * Hook to handle native messaging prompt functionality
 * Replicates the native messaging logic from the original block page
 */
export function useNativeMessaging(): UseNativeMessagingReturn {
  const [showNativeMessaging, setShowNativeMessaging] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Check if native messaging prompt is needed
    const checkNativeMessaging = () => {
      if (chrome?.runtime) {
        chrome.runtime.sendMessage(
          {
            type: MSG_IS_NEEDING_NATIVE_MSG,
            parameters: { source: 'contentControlBlockPage' }
          },
          (response) => {
            if (chrome.runtime.lastError) {
              console.error('Chrome Runtime Failure:', chrome.runtime.lastError);
            }
            
            setIsLoading(false);
            
            if (response?.needsIt) {
              setShowNativeMessaging(true);
            }
          }
        );
      } else {
        setIsLoading(false);
      }
    };

    checkNativeMessaging();
  }, []);

  const handleNativeMessagingResponse = async (accepted: boolean) => {
    try {
      let response;
      
      if (accepted) {
        // For now, we'll simulate the native messaging response
        // In the real implementation, this would call the actual native messaging utilities
        response = true;
      } else {
        response = false;
      }

      // Send settings update
      if (chrome?.runtime) {
        chrome.runtime.sendMessage(
          {
            type: MSG_SETTINGS_SET,
            payload: { [SETTING_NATIVE_MESSAGING]: response }
          },
          (settingsResponse) => {
            if (chrome.runtime.lastError) {
              console.error('Chrome Runtime Error:', chrome.runtime.lastError);
            }
            
            if (!settingsResponse || settingsResponse.error) {
              console.error('Settings update error:', settingsResponse?.error);
            } else {
              console.debug(`Native Messaging turned ${response ? 'on' : 'off'}`);
            }
            
            setShowNativeMessaging(false);
          }
        );
      } else {
        setShowNativeMessaging(false);
      }
    } catch (error) {
      console.error('Native messaging error:', error);
      setShowNativeMessaging(false);
    }
  };

  return {
    showNativeMessaging,
    isLoading,
    handleNativeMessagingResponse
  };
}
