import { useState, useEffect } from 'react';
import { chrome } from '@/utils/polyfill';
import type { AccessControlRow, AccessControlType, PermissionValue, AccessControlPermissions } from './types';

interface UseAccessControlDataReturn {
  data: AccessControlRow[] | null;
  loading: boolean;
  error: string | null;
  updatePermission: (siteUrl: string, permissionType: AccessControlType, newValue: string) => Promise<void>;
}

const CONTENT_SETTINGS_MAP: Record<AccessControlType, string> = {
  notifications: 'notifications',
  location: 'location',
  popup: 'popups',
  microphone: 'microphone',
  camera: 'camera',
};

const mapChromeSettingToPermissionValue = (chromeSetting: string): PermissionValue => {
  switch (chromeSetting) {
    case 'allow':
      return 'allow';
    case 'ask':
    case 'session_only':
      return 'ask';
    case 'block':
      return 'block';
    default:
      return 'default';
  }
};

const mapPermissionValueToChromeSetting = (permissionValue: PermissionValue): string => {
  switch (permissionValue) {
    case 'allow':
      return 'allow';
    case 'ask':
      return 'ask';
    case 'block':
      return 'block';
    default:
      return 'ask'; // Default to ask for most content settings
  }
};

export const useAccessControlData = (): UseAccessControlDataReturn => {
  const [data, setData] = useState<AccessControlRow[] | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchHistoryAndPermissions = async () => {
    try {
      setLoading(true);
      setError(null);

      // Get all history
      const historyItems = await chrome.history.search({
        text: '',
        startTime: 0,
        maxResults: 2147483647,
      });

      // Extract unique domains
      const domains = new Set<string>();
      historyItems.forEach(item => {
        if (item.url) {
          try {
            const url = new URL(item.url);
            // Only include http/https domains
            if (url.protocol === 'http:' || url.protocol === 'https:') {
              domains.add(url.hostname);
            }
          } catch (e) {
            // Skip invalid URLs
          }
        }
      });

      // Fetch content settings for each domain
      const accessControlData: AccessControlRow[] = [];
      
      for (const domain of Array.from(domains).slice(0, 100)) { // Limit to first 100 domains for performance
        try {
          const permissions: AccessControlPermissions = {};
          
          // Get permissions for each content setting type
          for (const [accessType, chromeType] of Object.entries(CONTENT_SETTINGS_MAP)) {
            try {
              const contentSettingsApi = (chrome.contentSettings as any)[chromeType];
              if (contentSettingsApi && contentSettingsApi.get) {
                const setting = await new Promise<{setting: string}>((resolve, reject) => {
                  contentSettingsApi.get({
                    primaryUrl: `https://${domain}/`,
                  }, (details: {setting: string} | undefined) => {
                    if (chrome.runtime.lastError) {
                      reject(new Error(chrome.runtime.lastError.message));
                    } else if (details) {
                      resolve(details);
                    } else {
                      resolve({setting: 'ask'}); // Default fallback
                    }
                  });
                });
                
                permissions[accessType as AccessControlType] = mapChromeSettingToPermissionValue(setting.setting);
              } else {
                permissions[accessType as AccessControlType] = 'default';
              }
            } catch (e) {
              console.warn(`Failed to get ${accessType} permission for ${domain}:`, e);
              // If we can't get a specific setting, set it as default
              permissions[accessType as AccessControlType] = 'default';
            }
          }

          // Only add domains that have at least one non-default permission
          const hasNonDefaultPermission = Object.values(permissions).some(perm => perm !== 'default');
          if (hasNonDefaultPermission) {
            accessControlData.push({
              id: domain,
              siteUrl: domain,
              permissions,
            });
          }
        } catch (e) {
          console.warn(`Failed to get permissions for domain: ${domain}`, e);
        }
      }

      setData(accessControlData);
    } catch (err) {
      console.error('Failed to fetch access control data:', err);
      setError(err instanceof Error ? err.message : 'Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const updatePermission = async (
    siteUrl: string, 
    permissionType: AccessControlType, 
    newValue: string
  ): Promise<void> => {
    try {
      console.log(`Updating permission for ${siteUrl}: ${permissionType} = ${newValue}`);
      
      // First check if we have the contentSettings permission
      const hasPermission = await chrome.permissions.contains({
        permissions: ['contentSettings']
      });
      
      if (!hasPermission) {
        throw new Error('Content settings permission not granted. Please grant permissions first.');
      }

      const chromeType = CONTENT_SETTINGS_MAP[permissionType];
      const chromeSetting = mapPermissionValueToChromeSetting(newValue as PermissionValue);
      
      console.log(`Chrome API: ${chromeType}, Setting: ${chromeSetting}`);
      
      const contentSettingsApi = (chrome.contentSettings as any)[chromeType];
      if (contentSettingsApi && contentSettingsApi.set) {
        await new Promise<void>((resolve, reject) => {
          contentSettingsApi.set({
            primaryPattern: `https://${siteUrl}/*`,
            setting: chromeSetting,
          }, () => {
            if (chrome.runtime.lastError) {
              console.error('Chrome runtime error:', chrome.runtime.lastError);
              reject(new Error(chrome.runtime.lastError.message));
            } else {
              console.log(`Successfully updated ${permissionType} for ${siteUrl} to ${chromeSetting}`);
              resolve();
            }
          });
        });
      } else {
        throw new Error(`Content settings API not available for ${permissionType}`);
      }

      // Update local state
      setData(prevData => {
        if (!prevData) return prevData;
        
        return prevData.map(row => {
          if (row.siteUrl === siteUrl) {
            return {
              ...row,
              permissions: {
                ...row.permissions,
                [permissionType]: newValue as PermissionValue,
              },
            };
          }
          return row;
        });
      });
    } catch (err) {
      console.error('Failed to update permission:', err);
      throw err;
    }
  };

  useEffect(() => {
    fetchHistoryAndPermissions();
  }, []);

  return {
    data,
    loading,
    error,
    updatePermission,
  };
};