// ABOUTME: Hook for managing manual ad removal data and operations
// ABOUTME: Handles loading, deleting blocked items using direct Chrome API calls

import { useState, useEffect, useMemo, useCallback } from 'react'
import { chrome } from '@/utils/polyfill'
import {
  MSG_GET_BLOCKED_ITEMS,
  MSG_DELETE_BLOCKED_ITEM,
  MSG_DELETE_ALL_BLOCKED_ITEMS,
} from '@/app/scripts/app-consts.js'

export type BlockedItemRow = {
  address: string
  xPath: string
}

export type BlockedItemsByDomain = {
  [domain: string]: Array<{ blockUrls: string[]; xpath: string }>
}

export type BlockedItemData = {
  domain: string
  blockUrls: string[]
  xpath: string
}

export const useManualAdRemoval = () => {
  const [blockedMap, setBlockedMap] = useState<BlockedItemsByDomain | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const loadBlockedItems = useCallback(async () => {
    try {
      setIsLoading(true)
      setError(null)

      const response: any = await new Promise((resolve) => {
        chrome.runtime.sendMessage(
          { type: MSG_GET_BLOCKED_ITEMS },
          (res: any) => {
            if (!res || res.error) {
              resolve({ items: {} })
              return
            }
            resolve(res)
          }
        )
      })

      const items = (response && response.items) || {}
      setBlockedMap(items)
    } catch (err: any) {
      setError(err?.message || 'Failed to load blocked items')
    } finally {
      setIsLoading(false)
    }
  }, [])

  const deleteBlockedItem = useCallback(async (item: BlockedItemData): Promise<boolean> => {
    try {
      const success: boolean = await new Promise((resolve) => {
        chrome.runtime.sendMessage(
          { type: MSG_DELETE_BLOCKED_ITEM, item },
          (res: any) => {
            if (!res || res.error) {
              resolve(false)
              return
            }
            resolve(Boolean(res.success))
          }
        )
      })

      if (!success) return false

      // Update local state by removing the matching entry
      const targetDomain = item.domain
      const targetXpath = (item.xpath || '').toUpperCase()

      setBlockedMap((prevMap) => {
        if (!prevMap) return prevMap
        
        const current = prevMap[targetDomain] || []
        const filtered = current.filter(
          (entry) => (entry.xpath || '').toUpperCase() !== targetXpath
        )
        
        return {
          ...prevMap,
          [targetDomain]: filtered
        }
      })

      return true
    } catch (_err) {
      return false
    }
  }, [])

  const deleteAllBlockedItems = useCallback(async (): Promise<boolean> => {
    try {
      const success: boolean = await new Promise((resolve) => {
        chrome.runtime.sendMessage(
          { type: MSG_DELETE_ALL_BLOCKED_ITEMS },
          (res: any) => {
            if (!res || res.error) {
              resolve(false)
              return
            }
            resolve(Boolean(res.success))
          }
        )
      })

      if (!success) return false

      setBlockedMap({})
      return true
    } catch (_err) {
      return false
    }
  }, [])

  // Transform blockedMap to table rows
  const rows = useMemo<BlockedItemRow[]>(() => {
    const list: BlockedItemRow[] = []
    if (!blockedMap) return list
    
    for (const [domain, entries] of Object.entries(blockedMap)) {
      for (const entry of entries) {
        list.push({ address: domain, xPath: entry.xpath })
      }
    }
    return list
  }, [blockedMap])

  // Load blocked items on mount
  useEffect(() => {
    loadBlockedItems().catch(console.error)
  }, [loadBlockedItems])

  return {
    rows,
    isLoading,
    error,
    loadBlockedItems,
    deleteBlockedItem,
    deleteAllBlockedItems,
  }
}