import React from 'react';
import { MenuButton } from '$Popup/components/core/BGContextMenu';
import { createBlockedItemMenuActions } from './logic';
import { BlockedItem } from './types';
import BGSvgIcon from '$Popup/components/core/BGSvgIcon';
import { t } from '$Popup/i18n';
/**
 * BlockedItemMenu - Menu content component for blocked item actions
 *
 * This component provides the menu content for blocked items in the DashboardTab.
 * It includes actions to toggle allow/block status for individual items or entire domains.
 *
 * Usage:
 * <Menu trigger={<button data-testid="button-3e3a6583" >...</button>}>
 *   <BlockedItemMenu item={blockedItem} currentHostname={hostname} onRefresh={handleRefresh} />
 * </Menu>
 */
interface BlockedItemMenuProps {
    /** The blocked item data */
    item: BlockedItem;
    /** The current hostname */
    currentHostname: string;
}

const BlockedItemMenu: React.FC<BlockedItemMenuProps> = ({ item, currentHostname }) => {
    const actions = createBlockedItemMenuActions(item, currentHostname);

    return (
        <MenuButton onClick={actions.toggleGranularAllow}>
            <div data-testid="div-58ef933e"  className="flex items-center text-xs">
                <BGSvgIcon iconName={Boolean(item.count) ? "allow" : "block"} size={14} className='mr-2' />
                {Boolean(item.count) ? t('allowListLabel') : t('blockContentLabel')}
            </div>
        </MenuButton>
    );
};

export default BlockedItemMenu;
