import { useState, useEffect, useCallback } from 'react';
import { sendBackgroundMessage } from '@/utils/messaging/messaging';
import { MSG_CONTENT_CONTROL_GET_ALL, MSG_CONTENT_CONTROL_REMOVE_ITEM, MSG_CONTENT_CONTROL_REMOVE_ALL } from '@/app/scripts/app-consts';
import type { BlockedWebsite, DeleteModalState } from './types';

// Marker to identify "delete all" operations
export const DELETE_ALL_MARKER = '__DELETE_ALL__';

// Transform content control data from background response
const transformContentControlData = (websites: string[]): BlockedWebsite[] => {
  return websites.map(domain => ({ domain }));
};

/**
 * Custom hook for managing content control data
 */
export const useContentControlData = (refreshKey?: number) => {
  const [websites, setWebsites] = useState<BlockedWebsite[]>([]);
  const [loading, setLoading] = useState(true);

  const loadContentControl = useCallback(async () => {
    try {
      setLoading(true);
      const response = await sendBackgroundMessage({ type: MSG_CONTENT_CONTROL_GET_ALL });
      
      if (response.success) {
        const websiteList = transformContentControlData(response.success);
        setWebsites(websiteList);
      }
    } catch (error) {
      console.error('Failed to load content control list:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadContentControl();
  }, [loadContentControl, refreshKey]);

  return { websites, loading, setWebsites, refetch: loadContentControl };
};

/**
 * Custom hook for managing delete operations
 */
export const useDeleteOperations = (websites: BlockedWebsite[], setWebsites: React.Dispatch<React.SetStateAction<BlockedWebsite[]>>) => {
  const [deleteModal, setDeleteModal] = useState<DeleteModalState>({
    isOpen: false,
    websiteToDelete: null,
    isDeleting: false
  });

  const openDeleteModal = useCallback((website: BlockedWebsite) => {
    setDeleteModal({
      isOpen: true,
      websiteToDelete: website,
      isDeleting: false
    });
  }, []);

  const openDeleteAllModal = useCallback(() => {
    setDeleteModal({
      isOpen: true,
      websiteToDelete: { domain: DELETE_ALL_MARKER },
      isDeleting: false
    });
  }, []);

  const closeDeleteModal = useCallback(() => {
    setDeleteModal({
      isOpen: false,
      websiteToDelete: null,
      isDeleting: false
    });
  }, []);

  const confirmDelete = useCallback(async () => {
    if (!deleteModal.websiteToDelete) return;

    setDeleteModal(prev => ({ ...prev, isDeleting: true }));

    try {
      if (deleteModal.websiteToDelete.domain === DELETE_ALL_MARKER) {
        // Delete all websites using the specific message
        const response = await sendBackgroundMessage({
          type: MSG_CONTENT_CONTROL_REMOVE_ALL
        });

        if (response.success || !response.error) {
          setWebsites([]);
        } else {
          console.error('Failed to delete all websites:', response.error);
        }
      } else {
        // Delete single website
        const response = await sendBackgroundMessage({
          type: MSG_CONTENT_CONTROL_REMOVE_ITEM,
          payload: { host: deleteModal.websiteToDelete.domain }
        });

        if (response.success || !response.error) {
          setWebsites(prev => prev.filter(w => w.domain !== deleteModal.websiteToDelete!.domain));
        } else {
          console.error('Failed to delete website:', response.error);
        }
      }

      closeDeleteModal();
    } catch (error) {
      console.error('Error deleting website(s):', error);
    } finally {
      setDeleteModal(prev => ({ ...prev, isDeleting: false }));
    }
  }, [deleteModal.websiteToDelete, websites, setWebsites, closeDeleteModal]);

  return {
    deleteModal,
    openDeleteModal,
    openDeleteAllModal,
    closeDeleteModal,
    confirmDelete
  };
};
