// ABOUTME: Reusable empty state component for tables
// ABOUTME: Shows folder icon with configurable title, description and optional link

import React from 'react'
import BGSvgIcon from '$Popup/components/core/BGSvgIcon'

interface TableEmptyStateProps {
  /** The main title/header text */
  title: string
  /** The description text */
  description: string
  /** Optional link object with href, text, and target */
  link?: {
    href: string
    text: string
    target?: string
    rel?: string
  }
  /** Optional icon name, defaults to 'folder' */
  iconName?: string
  /** Optional icon size, defaults to 168 */
  iconSize?: number
  /** Optional icon className, defaults to 'text-success' */
  iconClassName?: string
}

const TableEmptyState: React.FC<TableEmptyStateProps> = ({
  title,
  description,
  link,
  iconName = 'folder',
  iconSize = 168,
  iconClassName = 'text-success'
}) => {
  return (
    <div data-testid="div-687801c7"  className="flex flex-col items-center justify-center w-full px-10 py-12">
      {/* Title and Icon Container */}
      <div data-testid="div-7bcedd08"  className="flex flex-col items-center space-y-6">
        {/* Title */}
        <h3 data-testid="h3-31aca813"  className="text-xl font-medium text-tragic text-center">
          {title}
        </h3>

        {/* Icon Container */}
        <BGSvgIcon iconName={iconName} size={iconSize} className={iconClassName} />

        {/* Description and Optional Link */}
        <div data-testid="div-567ccb6c"  className="flex flex-col items-center space-y-2">
          {/* Description */}
          <p data-testid="p-ff97d576"  className="text-tragic-400 text-center text-base leading-6 max-w-[560px]">
            {description}
          </p>

          {/* Optional Link */}
          {link && (
            <a data-testid="a-33adb3db" 
              href={link.href}
              className="text-primary font-medium text-sm hover:underline"
              target={link.target || '_blank'}
              rel={link.rel || 'noopener noreferrer'}
            >
              {link.text}
            </a>
          )}
        </div>
      </div>
    </div>
  )
}

export default TableEmptyState