/**
 * Utility function to find menu item by id
 */
export const findMenuItemById = (items: HeaderMenuItem[], id: string): HeaderMenuItem | undefined => {
  return items.find(item => item.id === id);
};

/**
 * Utility function to filter menu items based on OS and browser compatibility
 * Premium items are always shown (with lock icons when needed)
 */
export const filterMenuItems = (
  items: HeaderMenuItem[],
  currentOs?: string[],
  currentBrowser?: string
): HeaderMenuItem[] => {
  return items.filter(item => {
    // Check OS compatibility - only filter if OS doesn't match
    if (item.showOs && currentOs && currentOs.length > 0) {
      const hasOsMatch = item.showOs.some(itemOs => currentOs.includes(itemOs));
      if (!hasOsMatch) {
        return false;
      }
    }

    // Check browser compatibility - only filter if browser doesn't match
    if (item.showBrowser && item.showBrowser.length > 0 && currentBrowser) {
      const hasBrowserMatch = item.showBrowser.some(
        itemBrowser => itemBrowser.toLowerCase() === currentBrowser.toLowerCase()
      );
      if (!hasBrowserMatch) {
        return false;
      }
    }

    // Always show premium items (lock icon will be displayed when needed)
    return true;
  });
};
