import { getCurrentTabData, refreshCurrentTab } from '$Popup/utils/tabData';
import { BlockedData, BlockedItem } from './types';
import {
    setAllowGranular,
} from '$Popup/utils/exclusionData';

// Constants
export const FALLBACK_HOSTNAME = "example.com";

// Static protection layer configuration
export const PROTECTION_LAYER_CARDS_CONFIG = [
    {
        name: "Ads/Tracker",
        description: chrome.i18n.getMessage('adstrackerLabel'),
        iconName: "announcement",
        key: "ads" as const
    },
    {
        name: "Malware",
        description: chrome.i18n.getMessage('malwareLabel'),
        iconName: "malware",
        key: "malware" as const
    },
    {
        name: "Scam",
        description: chrome.i18n.getMessage('scamLabel'),
        iconName: "suspicious",
        key: "scams" as const
    }
] as const;

/**
 * Processes blocked data into a flat list of blocked items with totals
 * @param blockedData - The blocked data from tab information
 * @param currentHostname - The current hostname being processed
 * @returns Object containing sorted blocked items and total count
 */
export const processBlockedData = async (
    blockedData: BlockedData | null,
    currentHostname: string,
    excluded?: Record<string, boolean>
): Promise<{ blockedItems: BlockedItem[]; totalBlockedItems: number }> => {
    if (!blockedData || !currentHostname) {
        return { blockedItems: [], totalBlockedItems: 0 };
    }

    const items: BlockedItem[] = [];
    for (const type of ['ads', 'malware', 'scams', 'content'] as const) {
        const categoryData = blockedData[type];
        const hostnameData = categoryData[currentHostname];

        if (hostnameData) {
            // re-write this to use async/await for clarity without changing logic and without forEach
            for (const [domain, count] of Object.entries(hostnameData)) {
                // If the item is in the exclusion/allowlist, set its count to 0
                const isExcluded = excluded && excluded[domain];
                items.push({
                    domain: domain,
                    count: isExcluded ? 0 : count,
                    type,
                    isDangerous: type === 'malware', // Only malware items are dangerous
                });
            }
        }
    }

    // Sort items: malware first (dangerous), then by count ascending
    const sortedItems = items.sort((a, b) => {
        if (a.isDangerous && !b.isDangerous) return -1;
        if (!a.isDangerous && b.isDangerous) return 1;
        return a.count - b.count;
    });

    // Calculate total
    const totalBlockedItems = items.reduce((sum, item) => sum + item.count, 0);

    return { blockedItems: sortedItems, totalBlockedItems };
};

/**
 * Creates protection layers configuration with current state and handlers
 * @param currentSiteProtections - Current protection settings for the site
 * @param toggleHandlers - Map of toggle handler functions
 * @returns Array of protection layer configurations
 */
export const createProtectionLayerCrads = (
    currentSiteProtections: any,
    toggleHandlers: Record<string, () => void>
) => {
    return PROTECTION_LAYER_CARDS_CONFIG.map(config => ({
        ...config,
        checked: currentSiteProtections[config.key],
        onChange: toggleHandlers[config.key]
    }));
};

/**
 * Creates a map of toggle handler functions for protection types
 * @param toggleSiteProtection - Function to toggle site protection
 * @param currentHostname - Current hostname
 * @returns Map of toggle handlers by protection type
 */
export const createToggleHandlers = (
    toggleSiteProtection: (hostname: string, type: 'ads' | 'malware' | 'scams') => void,
    currentHostname: string
) => ({
    ads: () => toggleSiteProtection(currentHostname, 'ads'),
    malware: () => toggleSiteProtection(currentHostname, 'malware'),
    scams: () => toggleSiteProtection(currentHostname, 'scams')
});


/**
 * Initializes the protection tab data by loading current tab information
 * and site protections, setting state accordingly.
 * @param setCurrentHostname - Function to set the current hostname
 * @param setBlockedData - Function to set blocked data state
 * @param setHasTabDataLoaded - Function to set tab data loaded state
 * @param setHasProtectionsLoaded - Function to set protections loaded state
 * @param loadSiteProtections - Function to load site protections
 * @param FALLBACK_HOSTNAME - Fallback hostname to use if no tab data is available
 * @return Promise that resolves when initialization is complete
 */
export const initializeProtectionTabData = async (
    setCurrentHostname: (hostname: string) => void,
    setBlockedData: (data: any) => void,
    setHasTabDataLoaded: (loaded: boolean) => void,
    setHasProtectionsLoaded: (loaded: boolean) => void,
    loadSiteProtections: (hostname: string) => Promise<void>,
    FALLBACK_HOSTNAME: string = 'unknown'
) => {
    try {
        // First, get current tab data
        const tabData = await getCurrentTabData();
        console.log('Current tab data from tabData:', tabData);

        const hostname = tabData?.host || FALLBACK_HOSTNAME;
        setCurrentHostname(hostname);

        // Save blocked data if available
        if (tabData?.blocked) {
            console.log('Blocked data:', tabData.blocked);
            setBlockedData(tabData.blocked);
        } else {
            console.warn('No blocked data found in tab data');
            setBlockedData(null);
        }

        setHasTabDataLoaded(true);

        // Load site protections for the actual hostname (not fallback)
        if (hostname !== FALLBACK_HOSTNAME) {
            console.log('React: Loading site protections for:', hostname);
            try {
                await loadSiteProtections(hostname);
                console.log('React: Site protections loaded successfully for:', hostname);
            } catch (error) {
                console.error('React: Failed to load protections for:', hostname, error);
            }
        }
    } catch (error) {
        console.error('Failed to get current tab data:', error);
        setCurrentHostname(FALLBACK_HOSTNAME);
        setBlockedData(null);
        setHasTabDataLoaded(true);
    } finally {
        setHasProtectionsLoaded(true);
    }
};

/**
 * Refreshes tab data and blocked items - useful after protection changes
 * @param setCurrentHostname - Function to set hostname
 * @param setBlockedData - Function to set blocked data
 * @param currentHostname - Current hostname for fallback
 * @returns Promise resolving to the updated data
 */
export const refreshTabData = async (
    setCurrentHostname?: (hostname: string) => void,
    setBlockedData?: (data: any) => void,
    currentHostname?: string
): Promise<{ hostname: string; blockedData: any }> => {
    try {
        console.log('Refreshing tab data after protection toggle...');
        const tabData = await getCurrentTabData();

        const hostname = tabData?.host || currentHostname || FALLBACK_HOSTNAME;

        if (setCurrentHostname) {
            setCurrentHostname(hostname);
        }

        const blockedData = tabData?.blocked || null;
        if (setBlockedData) {
            setBlockedData(blockedData);
        }

        console.log('Tab data refreshed:', { hostname, blockedData });
        return { hostname, blockedData };
    } catch (error) {
        console.error('Failed to refresh tab data:', error);
        const hostname = currentHostname || FALLBACK_HOSTNAME;
        if (setCurrentHostname) {
            setCurrentHostname(hostname);
        }
        if (setBlockedData) {
            setBlockedData(null);
        }
        return { hostname, blockedData: null };
    }
};

/**
 * Creates menu action handlers for blocked items
 */
export const createBlockedItemMenuActions = (
    item: BlockedItem,
    currentHostname: string,
) => {
    const toggleGranularAllow = async () => {
        try {
            // Toggle the current allow status
            const newValue = Boolean(item.count);

            // Use setAllowGranular to toggle the status
            await setAllowGranular({
                url: currentHostname,
                blockUrl: item.domain,
                value: newValue
            });

            // Refresh the browser tab so the change takes effect
            await refreshCurrentTab();

            // Close the popup so the page can reload cleanly
            window.close();
        } catch (error) {
            console.error('Failed to toggle granular allow status:', error);
        }
    };

    return {
        toggleGranularAllow
    };
};
