import * as React from "react";
import BGSvgIcon from "$Popup/components/core/BGSvgIcon";
import { t } from "$Popup/i18n";
interface UrlInputProps {
  value: string;
  onChange: (value: string) => void;
  isValid: boolean;
  disabled?: boolean;
}

export const UrlInput: React.FC<UrlInputProps> = ({ value, onChange, isValid, disabled = false }) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange(e.target.value);
  };

  const getInputClassName = () => {
    const baseClasses = "w-full px-3 py-3 border rounded-2xl text-sm text-tragic-400 focus:outline-none focus:ring-2 focus:ring-primary-300";

    if (isValid) {
      return `${baseClasses} border-success-300 bg-success-100`;
    } else if (value.length > 0) {
      return `${baseClasses} border-danger-300 bg-danger-100`;
    } else {
      return `${baseClasses} border-tragic-200 bg-backdrop`;
    }
  };

  return (
    <div data-testid="div-29307760"  className="flex flex-col space-y-3">
      <h4 data-testid="h4-594889c1"  className="text-sm font-normal text-tragic-400">
        {t("UrlInputField")}
      </h4>
      <div data-testid="div-0c9b97ac"  className="relative">
        <input data-testid="input-f8ff797f" 
          type="text"
          value={value}
          onChange={handleChange}
          placeholder="website.com or 192.168.1.1"
          className={getInputClassName()}
          disabled={disabled}
        />
        <BGSvgIcon 
          iconName="grey-link" 
          size={23} 
          className="absolute right-3 top-1/2 transform -translate-y-1/2" 
        />
      </div>
    </div>
  );
};
