import { createColumnHelper, type ColumnDef } from "@tanstack/react-table";
import BGSvgIcon from "$Popup/components/core/BGSvgIcon";
import BGContextMenu, { MenuButton } from "$Popup/components/core/BGContextMenu";
import { t } from "$Popup/i18n";
import { cn } from "$Popup/lib/utils";
import type { AccessControlRow, AccessControlType, PermissionValue } from "./types";

const columnHelper = createColumnHelper<AccessControlRow>();

const getPermissionDisplayInfo = (value: PermissionValue) => {
  switch (value) {
    case 'allow':
      return {
        text: t('allowAccess'),
        className: 'bg-warning-200 text-warning px-4 min-w-[60px] py-[3px] rounded-full text-sm font-medium',
      };
    case 'ask':
      return {
        text: t('askAccess'),
        className: 'bg-primary-100 text-primary px-4 min-w-[60px] py-[3px] rounded-full text-sm font-medium',
      };
    case 'block':
      return {
        text: t('blockAction'),
        className: 'bg-tragic-200 text-tragic-400 px-4 min-w-[60px] py-[3px] rounded-full text-sm font-medium',
      };
    default:
      return {
        text: 'Default',
        className: 'text-tragic-400 text-sm font-normal',
      };
  }
};

const getAvailableActions = (currentValue: PermissionValue, permissionType: AccessControlType): Array<{value: PermissionValue, label: string}> => {
  const allActions = [
    { value: 'allow' as PermissionValue, label: t('allowAccess') },
    { value: 'ask' as PermissionValue, label: t("askEveryTimeAccess") },
    { value: 'block' as PermissionValue, label: t('blockAccess') },
  ];
  
  // Popup permissions in Chrome only support 'allow' and 'block', not 'ask'
  const availableActions = permissionType === 'popup' 
    ? allActions.filter(action => action.value !== 'ask')
    : allActions;
  
  return availableActions.filter(action => action.value !== currentValue);
};

export const createColumns = (
  selectedType: AccessControlType,
  onPermissionChange: (siteUrl: string, permissionType: AccessControlType, newValue: string) => void,
  onBulkAction: (action: 'allow' | 'block' | 'ask') => void,
  hasData: boolean = true
): ColumnDef<AccessControlRow, any>[] => [
  columnHelper.accessor("siteUrl", {
    header: () => (
      <div data-testid="div-01144f2c"  className="flex items-center gap-2">
        <span data-testid="span-ca056a79">{t('SiteURL')}</span>
      </div>
    ),
    cell: (info) => (
      <span data-testid="span-0a69f415"  className="break-all text-sm font-medium text-tragic">
        {info.getValue()}
      </span>
    ),
    meta: {
      headerClassName: "text-left",
      cellClassName: "py-4 px-4 text-left",
      align: "left",
    },
  }),
  
  columnHelper.accessor((row) => row.permissions[selectedType], {
    id: "access",
    header: "Access",
    cell: (info) => {
      const value = info.getValue() as PermissionValue;
      const displayInfo = getPermissionDisplayInfo(value);
      
      return (
        <div data-testid="div-6067381f"  className="flex items-center justify-center">
          <span data-testid="span-04ac9d19"  className={displayInfo.className}>
            {displayInfo.text}
          </span>
        </div>
      );
    },
    meta: {
      headerClassName: "text-center",
      cellClassName: "py-4 px-4 text-center",
      align: "center",
    },
  }),
  
  columnHelper.display({
    id: "actions",
    header: () => hasData ? (
      <div data-testid="div-7079c5d8"  className="flex justify-end">
        <BGContextMenu
          trigger={
            <button data-testid="button-e058bc91"  className="p-1 hover:bg-gray-100 rounded transition-colors">
              <BGSvgIcon iconName="kebab-menu" size={16} className="opacity-40" />
            </button>
          }
        >
          <MenuButton onClick={() => onBulkAction('allow')}>
            {t('accessControlBulkAllowAll')}
          </MenuButton>
          <MenuButton onClick={() => onBulkAction('block')}>
            {t('accessControlBulkBlockAll')}
          </MenuButton>
          {selectedType !== 'popup' && (
            <MenuButton onClick={() => onBulkAction('ask')}>
              {t('accessControlBulkAskEveryTimeAll')}
            </MenuButton>
          )}
        </BGContextMenu>
      </div>
    ) : (
      <div data-testid="div-7079c5d8"  className="flex justify-end">
        <BGSvgIcon iconName="kebab-menu" size={16} className="opacity-40" />
      </div>
    ),
    cell: (info) => {
      const currentValue = info.row.original.permissions[selectedType] as PermissionValue;
      const availableActions = getAvailableActions(currentValue, selectedType);
      
      if (availableActions.length === 0) return null;

      return (
        <div data-testid="div-4eddb524"  className="flex justify-end">
          <BGContextMenu
            trigger={
              <button data-testid="button-a8492993"  
                className="p-2 hover:bg-tragic-100 rounded transition-colors shrink-0"
                aria-label={`Menu for ${info.row.original.siteUrl}`}
              >
                <BGSvgIcon
                  iconName="kebab-menu"
                  size={16}
                  className="opacity-60 hover:opacity-100 shrink-0"
                />
              </button>
            }
          >
            {availableActions.map((action) => (
              <MenuButton
                key={action.value}
                onClick={() => onPermissionChange(
                  info.row.original.siteUrl, 
                  selectedType, 
                  action.value
                )}
                className="hover:bg-primary-100"
              >
                {action.label}
              </MenuButton>
            ))}
          </BGContextMenu>
        </div>
      );
    },
    size: 60,
    minSize: 60,
    maxSize: 60,
    meta: {
      headerClassName: "w-15 text-right flex-shrink-0",
      cellClassName: "py-4 px-2 text-right flex-shrink-0",
      align: "right",
    },
  }),
];