import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { DataTable, TableEmptyState } from '$Popup/components/core/BGTable';
import { SegmentedFilters, Option } from '$Popup/components/DetectionHistory/SegmentedFilters';
import { createColumns } from './columns';
import { useAccessControlData } from './hooks';
import { AccessControlType, AccessFilterType } from './types';
import { t } from '$Popup/i18n';

/**
 * AccessControlTable Component - Table to display and manage access control rules
 * 
 * This component displays a table of access control rules when permissions are granted.
 * Users can navigate between different permission types and manage site permissions.
 */

const ACCESS_CONTROL_TYPES: Option[] = [
  { value: 'notifications', label: 'accessControlNotificationsTitle', iconName: 'notication-bell' },
  { value: 'location', label: 'accessControlLocationTitle', iconName: 'location-pin' },
  { value: 'popup', label: 'accessControlPopupTitle', iconName: 'megaphone' },
  { value: 'microphone', label: 'accessControlMicrophoneTitle', iconName: 'headset' },
  { value: 'camera', label: 'accessControlCameraTitle', iconName: 'video-cam' },
];

const AccessControlTable: React.FC = () => {
  const [selectedType, setSelectedType] = useState<AccessControlType>('notifications');
  const [selectedAccessFilter, setSelectedAccessFilter] = useState<AccessFilterType>('allow');
  const { data, loading, error, updatePermission } = useAccessControlData();

  // Dynamically generate access filter options based on selected type
  // Popup permissions don't support 'ask' in Chrome
  const accessFilterTypes: Option[] = useMemo(() => {
    const baseFilters = [
      { value: 'allow', label: 'allowAccess', iconName: 'allow' },
      { value: 'ask', label: 'askAccess', iconName: 'info' },
      { value: 'block', label: 'blockAction', iconName: 'block' },
    ];
    
    return selectedType === 'popup' 
      ? baseFilters.filter(f => f.value !== 'ask')
      : baseFilters;
  }, [selectedType]);

  // When switching to popup type, change filter if it's 'ask'
  useEffect(() => {
    if (selectedType === 'popup' && selectedAccessFilter === 'ask') {
      setSelectedAccessFilter('allow');
    }
  }, [selectedType, selectedAccessFilter]);

  // Filter data based on selected type and access filter
  const filteredData = useMemo(() => {
    if (!data || !selectedType) return [];
    
    return data.filter(row => {
      const setting = row.permissions[selectedType];
      // Filter by permission type (exclude defaults)
      if (!setting || setting === 'default') return false;
      
      // Filter by access type
      if (setting !== selectedAccessFilter) return false;
      
      return true;
    });
  }, [data, selectedType, selectedAccessFilter]);

  const handlePermissionChange = useCallback(async (
    siteUrl: string, 
    permissionType: AccessControlType, 
    newValue: string
  ) => {
    try {
      console.log(`Attempting to change ${permissionType} permission for ${siteUrl} to ${newValue}`);
      await updatePermission(siteUrl, permissionType, newValue);
      console.log('Permission updated successfully');
    } catch (error) {
      console.error(`Failed to update permission: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }, [updatePermission]);

  // Bulk action handlers
  const handleBulkAction = useCallback(async (action: 'allow' | 'block' | 'ask') => {
    if (!filteredData.length) return;

    try {
      console.log(`Performing bulk ${action} action for ${filteredData.length} sites`);
      
      // Map action to permission value
      const permissionValue = action === 'allow' ? 'allow' : action === 'block' ? 'block' : 'ask';
      
      // Update all filtered sites for the selected permission type
      const updatePromises = filteredData.map(row => 
        updatePermission(row.siteUrl, selectedType, permissionValue)
      );
      
      await Promise.all(updatePromises);
      console.log(`Bulk ${action} action completed successfully`);
    } catch (error) {
      console.error(`Failed to perform bulk action: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }, [filteredData, selectedType, updatePermission]);

  const columns = createColumns(selectedType, handlePermissionChange, handleBulkAction, filteredData.length > 0);

  // Get dynamic title and description based on selected type
  const getTypeDisplayInfo = (type: AccessControlType) => {
    const titleKey = `accessControl${type.charAt(0).toUpperCase() + type.slice(1)}Title`;
    const descriptionKey = `accessControl${type.charAt(0).toUpperCase() + type.slice(1)}Description`;
    return {
      title: t(titleKey),
      description: t(descriptionKey)
    };
  };

  const typeDisplayInfo = getTypeDisplayInfo(selectedType);

  if (loading) {
    return (
      <div data-testid="div-e7807018"  className="AccessControlTable">
        <SegmentedFilters 
          value={selectedType} 
          onChange={setSelectedType as (value: string) => void} 
          options={ACCESS_CONTROL_TYPES} 
        />
        <div data-testid="div-d976d388"  className="flex justify-center items-center py-8">
          <span data-testid="span-0a75d545">{t('Loading')}</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div data-testid="div-329f8e76"  className="AccessControlTable">
        <SegmentedFilters 
          value={selectedType} 
          onChange={setSelectedType as (value: string) => void} 
          options={ACCESS_CONTROL_TYPES} 
        />
        <div data-testid="div-9bad6099"  className="flex justify-center items-center py-8 text-danger">
          <span data-testid="span-8009bfaf">{t('errorLoadingAccessControlData')}</span>
        </div>
      </div>
    );
  }

  const emptyPermTitle = t(ACCESS_CONTROL_TYPES.find(type => type.value === selectedType)?.label || '').toLocaleLowerCase();
  const emptyStateTitle = t('accessControlEmptyStateTitle', [ emptyPermTitle ]);
  const emptyStateDescription = t('accessControlEmptyStateDescription');

  return (
    <div data-testid="div-3c1e49d1"  className="AccessControlTable space-y-4">
      <SegmentedFilters 
        value={selectedType} 
        onChange={setSelectedType as (value: string) => void} 
        options={ACCESS_CONTROL_TYPES} 
      />
      
      <SegmentedFilters 
        value={selectedAccessFilter} 
        onChange={setSelectedAccessFilter as (value: string) => void} 
        options={accessFilterTypes} 
      />

      <div data-testid="div-555899fc"  className='mt-5'>
        <h4 data-testid="h4-d967993e"  className='text-base font-medium text-tragic'>{typeDisplayInfo.title}</h4>
        <p data-testid="p-d3682b34"  className='text-sm text-tragic-400'>{typeDisplayInfo.description}</p>
      </div>
      
      <div data-testid="div-931191f3"  className="w-full">
        <DataTable
          columns={columns}
          data={filteredData}
          emptyState={
            <TableEmptyState
              title={emptyStateTitle}
              description={emptyStateDescription}
            />
          }
          enableSearch={true}
          searchPlaceholder={t('SearchDomainsPlaceholder')+"..."}
          enablePagination={true}
          pageSize={8}
        />
      </div>
    </div>
  );
};

export default AccessControlTable;
