import * as React from 'react'
import { useCarouselIndex, useCarouselControls } from './index'
import { cn } from '$Popup/lib/utils'
import { useTranslation } from '$Popup/i18n/hooks'

interface CarouselStepperProps {
  className?: string
  steps?: Array<{
    stepperTitle: string
  }>
  allowStepNavigation?: boolean
}

function CarouselStepper({ className, steps, allowStepNavigation = true }: CarouselStepperProps) {
  const { selectedIndex, totalSlides } = useCarouselIndex()
  const { scrollTo } = useCarouselControls()
  const { t } = useTranslation()

  // Default steps for onboarding modal - can be overridden via props
  // Note: Welcome step (index 0) and clipboard permissions step (index 1) are excluded from the stepper
  const defaultSteps = [
    { 
      stepperTitle: 'Pin extension'
    }
  ]

  const stepLabels = steps || defaultSteps

  const handleStepClick = React.useCallback(
    (index: number) => {
      // Add 2 to account for welcome page (index 0) and clipboard permissions page (index 1)
      scrollTo(index + 2)
    },
    [scrollTo]
  )

  // Calculate the number of stepper steps (exclude welcome page and clipboard permissions)
  const stepperSteps = totalSlides - 2
  // Current step in stepper context (0-based, excluding welcome page and clipboard permissions)
  const currentStepperIndex = selectedIndex - 2

  return (
    <div data-testid="div-866eaa36"  className={cn('flex items-center justify-center w-full p-4', className)}>
      {Array.from({ length: stepperSteps }, (_, index) => {
        const isActive = index === currentStepperIndex
        const isCompleted = index < currentStepperIndex
        const stepTitle = stepLabels[index]?.stepperTitle || `Step ${index + 1}`
        const isLast = index === stepperSteps - 1
        const isFirst = index === 0

        return (
          <React.Fragment key={index}>
            <div data-testid="div-e5c1cce6" 
              className={cn(
                {'mid-step-bridge': !isLast && !isFirst},
                {'right-step-bridge': isLast},
                {'left-step-bridge': isFirst},
                'relative flex flex-col items-center gap-2 group min-w-0',
                allowStepNavigation ? 'cursor-pointer' : 'cursor-default'
              )}
              onClick={allowStepNavigation ? () => handleStepClick(index) : undefined}
            >
              {/* Circle with number */}
              <div data-testid="div-e8f40e96" 
                className={cn(
                  'w-6 h-6 rounded-full flex items-center justify-center text-sm font-normal z-10',
                  isActive
                    ? 'bg-primary text-backdrop'
                    : isCompleted
                    ? 'bg-primary text-backdrop'
                    : 'bg-liteblue dark:bg-gray-800 dark:text-tragic'
                )}
                aria-label={`Go to ${stepTitle}`}
                aria-current={isActive}
              >
                {index + 1}
              </div>
              
              {/* Label */}
              <span data-testid="span-5f752cb3" 
                className={cn(
                  'text-xs font-normal text-center',
                  allowStepNavigation && 'group-hover:text-primary dark:group-hover:text-primary',
                  isActive
                    ? 'text-tragic-400'
                    : isCompleted
                    ? 'text-tragic-400'
                    : 'text-tragic-300'
                )}
              >
                {t(stepTitle)}
              </span>
            </div>
            
            {/* Separator line */}
            {!isLast && (
              <div data-testid="div-518d7455"  className="flex-1 h-px -mt-5 min-w-2" />
            )}
          </React.Fragment>
        )
      })}
    </div>
  )
}

export default CarouselStepper