import React from 'react';
import { Card } from '$Popup/components/core/BGCard';
import { useProtectionStatus } from './hooks';
import { ShieldStatus, ProtectionGrid } from './components';

/**
 * OverviewStatus Component - Protection status display
 * 
 * This component displays the overall protection status with a shield icon
 * and individual protection settings in a grid layout.
 */
const OverviewStatus: React.FC = () => {
    const { protectionStatus, protectionItems } = useProtectionStatus();

    return (
        <Card className="flex w-full max-w-full">
            <ShieldStatus protectionStatus={protectionStatus} />
            <ProtectionGrid protectionItems={protectionItems} />
        </Card>
    );
};

export default OverviewStatus;
