import { useState, useEffect } from 'react';
import { chrome } from '@/utils/polyfill';
import { SupportData } from '../types';
import { TARGET_BROWSER } from '@/app/scripts/browser-const';
import { BROWSER_NAME } from '@/app/scripts/app-consts';



/**
 * Hook for managing support data
 * Loads extension version and other static data
 */
export const useSupportData = (): SupportData => {
  const [version, setVersion] = useState<string>('');
  const [isLoading, setIsLoading] = useState<boolean>(true);
  // @ts-ignore
  const [showTelemetryToggle] = useState<boolean>(TARGET_BROWSER !== BROWSER_NAME.Firefox);

  useEffect(() => {
    const loadVersion = () => {
      try {
        const manifestData = chrome.runtime.getManifest();
        setVersion(manifestData.version);
      } catch (error) {
        console.error('Failed to load version:', error);
        setVersion('Unknown');
      } finally {
        setIsLoading(false);
      }
    };

    loadVersion();
  }, []);

  return {
    version,
    isLoading,
    showTelemetryToggle
  };
};
