/**
 * URL validation utilities for the AddAllowModal component
 */

/**
 * IP validation regex (from patterns.js)
 */
export const isValidIP = (ip: string): boolean => {
  const ipRegex = /^((25[0-5]|(2[0-4]|1[0-9]|[1-9]|)[0-9])(\.(?!$)|$)){4}$/;
  return ipRegex.test(ip);
};

/**
 * Clean hostname function (from utils.js)
 * Removes protocols, www prefix, trailing slashes and sanitizes input
 */
export const cleanHostname = (dirtyHost: string): string => {
  return dirtyHost
    .toLowerCase()
    .replace(/[<>]/g, "") // get rid of brackets
    .replace(/http[s]?:\/\//g, "") // get rid of protocol
    .replace("www.", "") // get rid of redundant subdomain
    .replace(/\/$/, "")
    .trim();
};

/**
 * Process input for allow list storage - handles both domains and IP addresses
 * For IPs: preserves the IP as-is
 * For domains: cleans and normalizes the domain
 */
export const processAllowListInput = (input: string): string => {
  if (!input || input.trim().length === 0) return '';
  
  const trimmed = input.trim();
  
  // Check if it's an IP address (after removing protocol if present)
  const cleanedInput = trimmed.replace(/^https?:\/\//, '');
  if (isValidIP(cleanedInput)) {
    return cleanedInput; // Return IP as-is
  }
  
  // For domains, use the existing cleaning logic
  return cleanHostname(trimmed);
};

/**
 * Check if a string contains only valid URL characters
 * Valid characters: A-Z, a-z, 0-9, -, ., _, ~, :, /, ?, #, [, ], @, !, $, &, ', (, ), +, ,, ;, %, =
 * Other characters must be URL-encoded (% followed by two hex digits)
 */
export const hasValidUrlCharacters = (input: string): boolean => {
  // Define the regex for valid URL characters
  // Including URL-encoded characters (%XX where XX are hex digits)
  const validUrlCharRegex = /^[A-Za-z0-9\-._~:/?#[\]@!$&'()+,;%=]*$/;
  
  // First check if all characters are in the allowed set
  if (!validUrlCharRegex.test(input)) {
    return false;
  }
  
  // Check that all % characters are properly followed by two hex digits
  const percentEncodeRegex = /%[0-9A-Fa-f]{2}/g;
  let processedInput = input;
  
  // Remove all valid percent-encoded sequences
  processedInput = processedInput.replace(percentEncodeRegex, '');
  
  // Check if any standalone % characters remain (invalid encoding)
  if (processedInput.includes('%')) {
    return false;
  }
  
  return true;
};

/**
 * Validate URL function (from utils.js isValidUrl)
 * Checks if input is valid, supporting both domains and IP addresses
 * Now includes validation for URL character restrictions
 */
export const validateUrl = (input: string): boolean => {
  if (!input || input.trim().length === 0) return false;
  
  const trimmed = input.trim();
  
  // Check if input contains only valid URL characters
  if (!hasValidUrlCharacters(trimmed)) {
    return false;
  }
  
  // Check if it's a valid IP address (with or without protocol)
  const cleanedForIP = trimmed.replace(/^https?:\/\//, '');
  if (isValidIP(cleanedForIP)) {
    return true;
  }
  
  try {
    // For domain validation, use existing logic
    const removeRedundant = trimmed.replace(/^(https?:\/\/)?(www\.)?/i, '');
    const str = cleanHostname(removeRedundant);

    // Basic checks for domains
    if (!str.startsWith('http') && (!str.includes('.') || str.endsWith('.'))) {
      return false;
    }

    // Domain length validation (3-253 characters)
    if (str.length < 3 || str.length > 253) {
      return false;
    }

    // Try to create a URL object to validate
    const url = new URL(str.startsWith('http') ? str : `http://${str}`);
    return !!url;
  } catch (error) {
    return false;
  }
};
