import { StateCreator } from 'zustand'
import {
  GeneralSettingsSlice,
  DEFAULT_GENERAL_SETTINGS,
} from '$Popup/store/types'
import {
  saveProtectionSetting,
  loadProtectionSettings,
  settingsGetAsync,
  CHROME_STORAGE_MAPPING,
} from '$Popup/store/chromeStorage/generalSettings'
import { chrome } from '@/utils/polyfill'

export const createGeneralSettingsSlice: StateCreator<GeneralSettingsSlice> = (
  set,
  get
) => ({
  // Initial state
  ...DEFAULT_GENERAL_SETTINGS,

  // Actions
  setGeneralSetting: (key, value) => {
    set((state) => ({
      ...state,
      [key]: value,
    }))
  },

  toggleGeneralProtection: async () => {
    const currentState = get().enableProtection
    const newState = !currentState

    // Update store immediately for UI responsiveness
    set((state) => ({
      ...state,
      enableProtection: newState,
      enableProtectionAds: newState,
      enableProtectionMalware: newState,
      enableProtectionScams: newState,
      enableMonthlyNotification: newState,
      enableMaliciousNotification: newState,
      enableBreachNotification: newState,
      enableNewReleaseNotification: newState,
      enableProfileCheckerNotification: newState,
      enableSearchHijackingNotification: newState,
      enableSkimmerProtection: newState,
      enableBlockCountDisplay: newState,
    }))

    try {
      // Save to Chrome storage
      await saveProtectionSetting('enableProtection', newState)

      await Promise.all([
        saveProtectionSetting('enableProtectionAds', newState),
        saveProtectionSetting('enableProtectionMalware', newState),
        saveProtectionSetting('enableProtectionScams', newState),
        saveProtectionSetting('enableMonthlyNotification', newState),
        saveProtectionSetting('enableMaliciousNotification', newState),
        saveProtectionSetting('enableBreachNotification', newState),
        saveProtectionSetting('enableNewReleaseNotification', newState),
        saveProtectionSetting('enableSearchHijackingNotification', newState),
        saveProtectionSetting('enableProfileCheckerNotification', newState),
        saveProtectionSetting('enableSkimmerProtection', newState),
        saveProtectionSetting('enableBlockCountDisplay', newState),
      ])
    } catch (error) {
      console.error('Failed to save general protection setting:', error)
      // Revert on error
      set((state) => ({
        ...state,
        enableProtection: currentState,
        enableProtectionAds: get().enableProtectionAds,
        enableProtectionMalware: get().enableProtectionMalware,
        enableProtectionScams: get().enableProtectionScams,
        enableMonthlyNotification: get().enableMonthlyNotification,
        enableMaliciousNotification: get().enableMaliciousNotification,
        enableBreachNotification: get().enableBreachNotification,
        enableNewReleaseNotification: get().enableNewReleaseNotification,
        enableSearchHijackingNotification: get().enableSearchHijackingNotification,
        enableProfileCheckerNotification: get().enableProfileCheckerNotification,
        enableSkimmerProtection: get().enableSkimmerProtection,
        enableBlockCountDisplay: get().enableBlockCountDisplay,
      }))
    }
  },

  toggleGeneralProtectionLayer: async (layer) => {
    const currentState = get()[layer]
    const newState = !currentState

    // Update store immediately for UI responsiveness
    set((state) => ({
      ...state,
      [layer]: newState,
    }))

    try {

      // Save to Chrome storage
      await saveProtectionSetting(layer as any, newState)

      // Read back the actual value from Chrome storage to ensure consistency
      const actualValue = await settingsGetAsync(
        CHROME_STORAGE_MAPPING[layer as any].settingKey
      )

      // Update store with the actual value from Chrome storage
      set((state) => ({
        ...state,
        [layer]: actualValue,
      }))
    } catch (error) {
      console.error(`Failed to save general protection layer ${layer}:`, error)
      // Revert on error
      set((state) => ({
        ...state,
        [layer]: currentState,
      }))
    }
  },

  toggleClipboardPermission: async () => {
    const currentState = get().enableClipboardReadPermission
    const newState = !currentState

    // Update store immediately for UI responsiveness
    set((state) => ({
      ...state,
      enableClipboardReadPermission: newState,
    }))

    try {
      if (newState) {
        // Request clipboard permission
        const granted = await new Promise<boolean>((resolve) => {
          chrome.permissions.request({ permissions: ['clipboardRead'] }, (granted) => {
            resolve(!!granted)
          })
        })

        // Update store with actual permission state
        set((state) => ({
          ...state,
          enableClipboardReadPermission: granted,
        }))
      } else {
        // Remove clipboard permission
        const removed = await new Promise<boolean>((resolve) => {
          chrome.permissions.remove({ permissions: ['clipboardRead'] }, (removed) => {
            resolve(!!removed)
          })
        })

        // Update store with actual permission state
        set((state) => ({
          ...state,
          enableClipboardReadPermission: !removed,
        }))
      }
    } catch (error) {
      console.error('Failed to toggle clipboard permission:', error)
      // Revert on error
      set((state) => ({
        ...state,
        enableClipboardReadPermission: currentState,
      }))
    }
  },

  togglePrivacyPermission: async () => {
    const currentState = get().enablePrivacyPermission
    const newState = !currentState

    // Update store immediately for UI responsiveness
    set((state) => ({
      ...state,
      enablePrivacyPermission: newState,
    }))

    try {
      if (newState) {
        // Request privacy permission
        const granted = await new Promise<boolean>((resolve) => {
          chrome.permissions.request({ permissions: ['privacy'] }, (granted) => {
            resolve(!!granted)
          })
        })

        if (granted) {
          // Disable network prediction to prevent tracking
          try {
            await new Promise<void>((resolve, reject) => {
              chrome.privacy.network.networkPredictionEnabled.set({ value: false }, () => {
                if (chrome.runtime.lastError) {
                  reject(chrome.runtime.lastError)
                } else {
                  resolve()
                }
              })
            })
          } catch (privacyError) {
            console.error('Failed to disable network prediction:', privacyError)
          }
        }

        // Update store with actual permission state
        set((state) => ({
          ...state,
          enablePrivacyPermission: granted,
        }))
      } else {
        // Remove privacy permission
        const removed = await new Promise<boolean>((resolve) => {
          chrome.permissions.remove({ permissions: ['privacy'] }, (removed) => {
            resolve(!!removed)
          })
        })

        if (removed && chrome.privacy && chrome.privacy.network) {
          // Re-enable network prediction when permission is revoked
          try {
            await new Promise<void>((resolve, reject) => {
              chrome.privacy.network.networkPredictionEnabled.set({ value: true }, () => {
                if (chrome.runtime.lastError) {
                  reject(chrome.runtime.lastError)
                } else {
                  resolve()
                }
              })
            })
          } catch (privacyError) {
            console.error('Failed to re-enable network prediction:', privacyError)
          }
        }

        // Update store with actual permission state
        set((state) => ({
          ...state,
          enablePrivacyPermission: !removed,
        }))
      }
    } catch (error) {
      console.error('Failed to toggle privacy permission:', error)
      // Revert on error
      set((state) => ({
        ...state,
        enablePrivacyPermission: currentState,
      }))
    }
  },

  // Load settings from Chrome storage
  loadGeneralSettings: async () => {
    try {
      // Set loading state
      set((state) => ({ ...state, isLoading: true }))

      const settings = await loadProtectionSettings()

      // Check clipboard permission status
      const clipboardPermissionGranted = await new Promise<boolean>((resolve) => {
        chrome.permissions.contains({ permissions: ['clipboardRead'] }, (result) => {
          resolve(!!result)
        })
      })

      // Check privacy permission status
      const privacyPermissionGranted = await new Promise<boolean>((resolve) => {
        chrome.permissions.contains({ permissions: ['privacy'] }, (result) => {
          resolve(!!result)
        })
      })
      // Load AI Scanner popover state from local storage
      const { hasSeenAiScannerPopover } = await chrome.storage.local.get('hasSeenAiScannerPopover')

      set((state) => ({
        ...state,
        ...settings,
        enableClipboardReadPermission: clipboardPermissionGranted,
        enablePrivacyPermission: privacyPermissionGranted,
        // If hasSeenAiScannerPopover is undefined (first time), default to false (show popover)
        // If it's explicitly true, keep it true (hide popover)
        hasSeenAiScannerPopover: hasSeenAiScannerPopover === true,
        isLoading: false,
      }))
    } catch (error) {
      console.error('Failed to load general settings:', error)
      // Set loading to false even on error
      set((state) => ({ ...state, isLoading: false }))
    }
  },

  dismissAiScannerPopover: async () => {
    set({ hasSeenAiScannerPopover: true })
    try {
      await chrome.storage.local.set({ hasSeenAiScannerPopover: true })
    } catch (error) {
      console.error('Failed to save AI Scanner popover state:', error)
    }
  },
})
