// ABOUTME: Background script helper for injecting React components into web pages
// ABOUTME: Simplifies chrome.scripting.executeScript API with error handling and retries

import { PositionPreset } from "./inject-component";

/**
 * Configuration for injecting a component from background script
 */
export interface BackgroundInjectConfig {
    /** Tab ID to inject into */
    tabId: number;
    /** Component name (must be registered in injectable-bundle) */
    componentName: string;
    /** Props to pass to component */
    props?: Record<string, any>;
    /** Container configuration */
    container?: {
        id?: string;
        position?: PositionPreset | React.CSSProperties;
        zIndex?: number;
    };
    /** Inject in all frames (default: false, main frame only) */
    allFrames?: boolean;
    /** Frame ID to inject into (if not allFrames) */
    frameId?: number;
}

/**
 * Result from injecting a component
 */
export interface InjectComponentResult {
    /** Success status */
    success: boolean;
    /** Component ID if successful */
    componentId?: string;
    /** Error message if failed */
    error?: string;
}

/**
 * Inject a React component into a web page from background script
 * 
 * @param config - Injection configuration
 * @returns Result with component ID or error
 * 
 * @example
 * ```ts
 * // In background script or service worker:
 * const result = await injectComponent({
 *   tabId: activeTab.id,
 *   componentName: 'ExampleNotification',
 *   props: {
 *     title: 'Welcome!',
 *     message: 'This is an injected notification',
 *     type: 'success',
 *     autoDismiss: 5000,
 *   },
 *   container: {
 *     position: 'top-right',
 *   },
 * });
 * 
 * if (result.success) {
 *   console.log('Component injected:', result.componentId);
 * } else {
 *   console.error('Injection failed:', result.error);
 * }
 * ```
 */
export async function injectComponent(config: BackgroundInjectConfig): Promise<InjectComponentResult> {
    const { tabId, componentName, props = {}, container = {}, allFrames = false, frameId } = config;

    try {
        // First, inject the injectable-bundle.js if not already loaded
        // We do this by checking if window.injectBGComponent exists in all target frames
        const checkResults = await chrome.scripting.executeScript({
            target: { tabId, allFrames, frameIds: frameId !== undefined ? [frameId] : undefined },
            func: () => typeof window.injectBGComponent !== 'undefined',
        });

        // When allFrames: true, we get one result per frame. Only skip injection if ALL frames have the bundle.
        const bundleLoaded = checkResults.length > 0 && checkResults.every(r => r?.result);

        if (!bundleLoaded) {
            await chrome.scripting.executeScript({
                target: { tabId, allFrames, frameIds: frameId !== undefined ? [frameId] : undefined },
                files: ['injectable-bundle.js'],
            });
        }

        // Now inject the component
        const results = await chrome.scripting.executeScript({
            target: { tabId, allFrames, frameIds: frameId !== undefined ? [frameId] : undefined },
            func: (args) => {
                return window.injectBGComponent(args);
            },
            args: [{ componentName, props, config: container }],
        });

        const componentId = results[0]?.result;

        if (!componentId) {
            return {
                success: false,
                error: `Component injection failed. Component may not be registered: ${componentName}`,
            };
        }

        return {
            success: true,
            componentId,
        };

    } catch (error) {
        console.error(`[BG Helper] Error injecting component:`, error);
        return {
            success: false,
            error: error instanceof Error ? error.message : String(error),
        };
    }
}

/**
 * Destroy a specific injected component
 * 
 * @param tabId - Tab ID
 * @param componentId - Component ID returned from injectComponent
 * @returns true if destroyed
 */
export async function destroyComponent(tabId: number, componentId: string): Promise<boolean> {

    try {
        const results = await chrome.scripting.executeScript({
            target: { tabId },
            func: (id) => {
                if (typeof window.destroyBGComponent !== 'undefined') {
                    return window.destroyBGComponent(id);
                }
                return false;
            },
            args: [componentId],
        });

        return results[0]?.result || false;
    } catch (error) {
        console.error(`[BG Helper] Error destroying component:`, error);
        return false;
    }
}

/**
 * Destroy all injected components in a tab
 * 
 * @param tabId - Tab ID
 */
export async function destroyAllComponents(tabId: number): Promise<void> {
    try {
        await chrome.scripting.executeScript({
            target: { tabId },
            func: () => {
                if (typeof window.destroyAllBGComponents !== 'undefined') {
                    window.destroyAllBGComponents();
                }
            },
        });
    } catch (error) {
        console.error(`[BG Helper] Error destroying all components:`, error);
    }
}

/**
 * Get list of available component names
 * 
 * @param tabId - Tab ID with injectable bundle loaded
 * @returns Array of component names
 */
export async function getAvailableComponents(tabId: number): Promise<string[]> {
    try {
        const results = await chrome.scripting.executeScript({
            target: { tabId },
            func: () => {
                if (typeof window.getBGComponentNames !== 'undefined') {
                    return window.getBGComponentNames();
                }
                return [];
            },
        });

        return results[0]?.result || [];
    } catch (error) {
        console.error(`[BG Helper] Error getting available components:`, error);
        return [];
    }
}
