// ABOUTME: Route-level access control that reuses LeftSidebar item filter functions
// ABOUTME: to determine which routes are accessible based on OS, language, feature flags, and browser.

import { RouteProps } from './types';
import {
  filterMenuItemsByOS,
  filterMenuItemsByLanguage,
  filterMenuItemsByFeatureFlags,
  filterMenuItemsByBrowser,
} from '$Popup/components/Layout/LeftSidebar/utils';
import { OperatingSystem } from '$Popup/utils/general';

/**
 * Context object containing the current environment for route filtering
 */
export interface RouteFilterContext {
  os: OperatingSystem;
  language: string;
  browser: string;
  featureFlags: Record<string, boolean>;
}

/**
 * Checks whether a specific route path is allowed given the current environment.
 * Runs all filters (OS, language, browser, feature flags) against the full
 * route list and checks if the target path survives filtering.
 *
 * Reuses the same item-level filter functions from LeftSidebar/utils to keep
 * sidebar visibility and route access rules in sync.
 *
 * @param path - The route path to check (without leading slash)
 * @param allRoutes - All route configs to filter against
 * @param context - Current environment context (OS, language, browser, flags)
 * @returns true if the route is allowed or not found in the route list (unguarded)
 */
export const isRouteAllowed = (
  path: string,
  allRoutes: RouteProps[],
  context: RouteFilterContext
): boolean => {
  // Check if this path exists in the known routes
  const routeExists = allRoutes.some(r => r.path === path);

  // If the path is not in the known routes, allow it (unguarded paths like catch-all)
  if (!routeExists) {
    return true;
  }

  // Run all filters and check if the target path survives.
  // RouteProps is structurally compatible with MenuItem for filter-relevant fields.
  let filtered: RouteProps[] = filterMenuItemsByOS(allRoutes, context.os) as RouteProps[];
  filtered = filterMenuItemsByLanguage(filtered, context.language) as RouteProps[];
  filtered = filterMenuItemsByFeatureFlags(filtered, context.featureFlags) as RouteProps[];
  filtered = filterMenuItemsByBrowser(filtered, context.browser) as RouteProps[];

  return filtered.some(r => r.path === path);
};
